// Keep compact-QC preflight at least as strict as State's full-entry admission
// before allocating transport. These are first-release protocol caps, not
// runtime tuning knobs.
const MAX_FETCH_MERGE_SIGNER_PROOFS: usize = 4_096;
const MAX_FETCH_MERGE_VALIDATORS: usize = 4_096;
const MAX_FETCH_MERGE_QC_BYTES: usize = 4 * 1024 * 1024;
const MERGE_QC_PROOF_BYTES: usize = 96;
const MERGE_QC_AUTH_CACHE_DOMAIN: &[u8] = b"iroha:sumeragi:v2:merge-qc-auth-cache:v1\0";
/// Maximum progress-bearing sidecar effects drained before one queued,
/// replayable responder control receives its own scheduler turn.
const SIDECAR_PROGRESS_DRAIN_WEIGHT: u8 = 3;
#[cfg(test)]
fn classify_committed_lane_block_execution_status(
    receipt_conflicts: impl FnOnce() -> bool,
    matching_receipt: impl FnOnce() -> Option<LaneBlockApplicationReceiptArtifactFormat>,
    predecessor_is_applied: impl FnOnce() -> bool,
    matching_preflight_has_rejections: impl FnOnce() -> Option<bool>,
    matching_execution_input_is_available: impl FnOnce() -> bool,
    payload_is_recoverable: impl FnOnce() -> bool,
) -> super::status::CommittedLaneBlockExecutionStatus {
    use super::status::CommittedLaneBlockExecutionStatus as Status;
    if receipt_conflicts() {
        return Status::ApplicationReceiptConflictsWithPreflight;
    }
    if matching_receipt().is_some() {
        return Status::StateAppliedByCanonicalBlock;
    }
    if !predecessor_is_applied() {
        return Status::AwaitingPredecessorApplication;
    }
    if let Some(has_rejections) = matching_preflight_has_rejections() {
        return if has_rejections {
            Status::PayloadPreflightRejectedAwaitingStateApplication
        } else {
            Status::PayloadPreflightedAwaitingStateApplication
        };
    }
    if matching_execution_input_is_available() {
        return Status::PayloadRecoveredAwaitingStateApplication;
    }
    if payload_is_recoverable() {
        return Status::PayloadAvailableAwaitingExecutor;
    }
    Status::AwaitingExecutablePayload
}
fn preferred_merge_candidates<T: Clone>(
    authorized_digest: Option<Hash>,
    relays: Vec<T>,
    installed: Vec<T>,
    digest: impl Fn(&T) -> Hash,
) -> Vec<T> {
    let mut available = relays.iter().chain(&installed).cloned().collect::<Vec<_>>();
    let mut seen = BTreeSet::new();
    available.retain(|candidate| seen.insert(digest(candidate)));
    if let Some(authorized_digest) = authorized_digest {
        return available
            .into_iter()
            .find(|candidate| digest(candidate) == authorized_digest)
            .into_iter()
            .collect();
    }
    if !relays.is_empty() {
        return relays;
    }
    installed
}
fn lane_proposal_carries_incarnation(
    proposal: &LaneBlockProposalV1,
    lane_id: LaneId,
    dataspace_id: DataSpaceId,
    lane_incarnation: Hash,
) -> bool {
    let descriptor = &proposal.descriptor;
    descriptor.lane_id == lane_id
        && descriptor.dataspace_id == dataspace_id
        && descriptor.lane_incarnation == lane_incarnation
}
fn native_amx_receipt_carries_separate_participant_incarnation(
    receipt: &NativeAmxReceipt,
    lane_id: LaneId,
    dataspace_id: DataSpaceId,
    lane_incarnation: Hash,
) -> bool {
    crate::native_amx::native_amx_receipt_requires_separate_participant_application_for(
        receipt,
        lane_id,
        dataspace_id,
        lane_incarnation,
    )
    .unwrap_or(true)
}
fn lane_executable_payload_carries_lane(
    payload: &LaneExecutablePayloadV1,
    lane_id: LaneId,
    dataspace_id: DataSpaceId,
    lane_incarnation: Hash,
) -> bool {
    if lane_proposal_carries_incarnation(
        &payload.origin_proposal,
        lane_id,
        dataspace_id,
        lane_incarnation,
    ) {
        return true;
    }
    let entry_count = payload.entrypoints.len();
    if payload.entrypoint_hashes.len() != entry_count
        || payload.reservation_keys.len() != entry_count
        || payload.routing_plans.len() != entry_count
        || payload.native_amx_receipts.len() != entry_count
    {
        return true;
    }
    let descriptor = &payload.origin_proposal.descriptor;
    payload
        .entrypoints
        .iter()
        .zip(&payload.entrypoint_hashes)
        .zip(&payload.reservation_keys)
        .zip(&payload.routing_plans)
        .zip(&payload.native_amx_receipts)
        .any(
            |((((entrypoint, entrypoint_hash), reservation), routing_plan), receipt)| {
                let computed_entrypoint_hash = entrypoint.hash();
                if Hash::from(computed_entrypoint_hash) != *entrypoint_hash
                    || reservation.validate().is_err()
                    || reservation.entrypoint_hash != computed_entrypoint_hash
                    || reservation.routing_plan_digest != routing_plan.digest()
                    || reservation.coordinator_leg != routing_plan.coordinator_leg()
                    || reservation.lane_id != descriptor.lane_id
                    || reservation.dataspace_id != descriptor.dataspace_id
                    || reservation.lane_incarnation != descriptor.lane_incarnation
                    || reservation.proposal_height != descriptor.proposal_height
                    || reservation.lane_block_height != descriptor.lane_block_height
                    || reservation.lane_block_view != descriptor.lane_block_view
                    || !crate::native_amx::receipt_shape_matches_coordinator_payload(
                        receipt.as_ref(),
                        routing_plan,
                        reservation.entrypoint_hash.as_ref(),
                        *entrypoint_hash,
                        payload.network_id,
                        &payload.origin_proposal,
                    )
                {
                    return true;
                }
                receipt.as_ref().is_some_and(|receipt| {
                    native_amx_receipt_carries_separate_participant_incarnation(
                        receipt,
                        lane_id,
                        dataspace_id,
                        lane_incarnation,
                    )
                })
            },
        )
}
fn merge_lane_execution_carries_lane(
    execution: &iroha_data_model::merge::MergeLaneExecution,
    lane_id: LaneId,
    dataspace_id: DataSpaceId,
    lane_incarnation: Hash,
) -> bool {
    if lane_proposal_carries_incarnation(
        &execution.proposal,
        lane_id,
        dataspace_id,
        lane_incarnation,
    ) || lane_proposal_carries_incarnation(
        &execution.origin_proposal,
        lane_id,
        dataspace_id,
        lane_incarnation,
    ) {
        return true;
    }
    let certified = &execution.proposal.descriptor;
    let origin = &execution.origin_proposal.descriptor;
    let entry_count = execution.entrypoints.len();
    if certified.lane_id != origin.lane_id
        || certified.dataspace_id != origin.dataspace_id
        || certified.lane_incarnation != origin.lane_incarnation
        || execution.entrypoint_hashes.len() != entry_count
        || execution.reservation_keys.len() != entry_count
        || execution.routing_plans.len() != entry_count
        || execution.native_amx_receipts.len() != entry_count
        || execution.result_hashes.len() != entry_count
        || execution.results.len() != entry_count
    {
        return true;
    }
    execution
        .entrypoints
        .iter()
        .zip(&execution.entrypoint_hashes)
        .zip(&execution.reservation_keys)
        .zip(&execution.routing_plans)
        .zip(&execution.native_amx_receipts)
        .any(
            |((((entrypoint, entrypoint_hash), encoded_reservation), encoded_plan), receipt)| {
                let Some(reservation) = decode_canonical_merge_reservation_key(encoded_reservation)
                else {
                    return true;
                };
                let Some(routing_plan) = decode_canonical_merge_routing_plan(encoded_plan) else {
                    return true;
                };
                let computed_entrypoint_hash = entrypoint.hash();
                if Hash::from(computed_entrypoint_hash) != *entrypoint_hash
                    || reservation.validate().is_err()
                    || reservation.entrypoint_hash != computed_entrypoint_hash
                    || reservation.routing_plan_digest != routing_plan.digest()
                    || reservation.coordinator_leg != routing_plan.coordinator_leg()
                    || reservation.lane_id != origin.lane_id
                    || reservation.dataspace_id != origin.dataspace_id
                    || reservation.lane_incarnation != origin.lane_incarnation
                    || reservation.proposal_height != origin.proposal_height
                    || reservation.lane_block_height != origin.lane_block_height
                    || reservation.lane_block_view != origin.lane_block_view
                    || !crate::native_amx::receipt_shape_matches_coordinator_payload(
                        receipt.as_ref(),
                        &routing_plan,
                        reservation.entrypoint_hash.as_ref(),
                        *entrypoint_hash,
                        execution.autonomous_network_id,
                        &execution.origin_proposal,
                    )
                {
                    return true;
                }
                receipt.as_ref().is_some_and(|receipt| {
                    native_amx_receipt_carries_separate_participant_incarnation(
                        receipt,
                        lane_id,
                        dataspace_id,
                        lane_incarnation,
                    )
                })
            },
        )
}
fn decode_canonical_merge_reservation_key(encoded: &[u8]) -> Option<LaneQueueReservationKeyV1> {
    norito::decode_canonical(encoded).ok()
}
fn decode_canonical_merge_routing_plan(encoded: &[u8]) -> Option<RoutingPlan> {
    norito::decode_canonical(encoded).ok()
}
fn merge_execution_batch_carries_lane(
    batch: &iroha_data_model::merge::MergeExecutionBatch,
    lane_id: LaneId,
    dataspace_id: DataSpaceId,
    lane_incarnation: Hash,
) -> bool {
    batch.lanes.iter().any(|execution| {
        merge_lane_execution_carries_lane(execution, lane_id, dataspace_id, lane_incarnation)
    })
}
fn merge_candidate_carries_lane(
    candidate: &crate::merge::MergeLedgerCandidate,
    lane_id: LaneId,
    dataspace_id: DataSpaceId,
    lane_incarnation: Hash,
) -> bool {
    candidate.lane_snapshots.iter().any(|snapshot| {
        snapshot.lane_id == lane_id
            && snapshot.dataspace_id == dataspace_id
            && snapshot.lane_incarnation == lane_incarnation
    }) || candidate.execution_batch.as_ref().is_some_and(|batch| {
        merge_execution_batch_carries_lane(batch, lane_id, dataspace_id, lane_incarnation)
    }) || candidate.lane_drain_certificates.iter().any(|certificate| {
        let intent = &certificate.body.intent;
        intent.lane_id == lane_id
            && intent.dataspace_id == dataspace_id
            && intent.lane_incarnation == lane_incarnation
    })
}
fn merge_entry_carries_lane(
    entry: &MergeLedgerEntry,
    lane_id: LaneId,
    dataspace_id: DataSpaceId,
    lane_incarnation: Hash,
) -> bool {
    entry.lane_snapshots.iter().any(|snapshot| {
        snapshot.lane_id == lane_id
            && snapshot.dataspace_id == dataspace_id
            && snapshot.lane_incarnation == lane_incarnation
    }) || entry.execution_batch.as_ref().is_some_and(|batch| {
        merge_execution_batch_carries_lane(batch, lane_id, dataspace_id, lane_incarnation)
    }) || entry.lane_drain_certificates.iter().any(|certificate| {
        let intent = &certificate.body.intent;
        intent.lane_id == lane_id
            && intent.dataspace_id == dataspace_id
            && intent.lane_incarnation == lane_incarnation
    })
}
/// Authenticated source for the sole height-one projection which is not yet
/// available from committed state.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum AuthenticatedGenesisNexusAmxContext {
    /// Projection recomputed from the validated, uncommitted genesis overlay.
    Staged(StagedGenesisNexusAmxContext),
}
impl AuthenticatedGenesisNexusAmxContext {
    const fn hash(self) -> Hash {
        match self {
            Self::Staged(staged) => staged.hash(),
        }
    }
}
fn validate_merge_sidecar_reference_bounds(
    context: &wire::HeightContext,
    reference: &CertifiedMergeLedgerReference,
) -> Result<(), String> {
    let qc = &reference.merge_qc;
    if reference.version != CERTIFIED_MERGE_SIDECAR_VERSION_V1
        || reference.encoded_len == 0
        || reference.encoded_len > u64::try_from(MAX_MERGE_LEDGER_ENTRY_BYTES).unwrap_or(u64::MAX)
        || reference.epoch_id != qc.epoch_id
    {
        return Err("certified merge reference has invalid length or epoch metadata".to_owned());
    }
    let execution_fields = [
        reference.execution_batch_hash.is_some(),
        reference.entrypoint_count.is_some(),
        reference.entrypoint_merkle_root.is_some(),
        reference.result_merkle_root.is_some(),
        reference.base_state_height.is_some(),
        reference.base_state_hash.is_some(),
    ];
    if execution_fields.iter().any(|present| *present)
        && !execution_fields.iter().all(|present| *present)
    {
        return Err("certified merge reference has a partial execution projection".to_owned());
    }
    if let Some(entrypoint_count) = reference.entrypoint_count
        && !(1..=u64::try_from(MAX_MERGE_EXECUTION_ENTRYPOINTS).unwrap_or(u64::MAX))
            .contains(&entrypoint_count)
    {
        return Err(
            "certified merge reference has an invalid execution entrypoint count".to_owned(),
        );
    }
    if qc.network_id != context.network_id {
        return Err("certified merge reference is bound to another network".to_owned());
    }
    let expected_bitmap_len = qc.validator_set.len().div_ceil(8);
    if qc.validator_set.len() > MAX_FETCH_MERGE_VALIDATORS
        || qc.signer_proofs.len() > MAX_FETCH_MERGE_SIGNER_PROOFS
        || qc.signers_bitmap.len() != expected_bitmap_len
        || qc.aggregate_signature.len() != MERGE_QC_PROOF_BYTES
        || qc
            .signer_proofs
            .iter()
            .any(|proof| proof.proof_of_possession.len() != MERGE_QC_PROOF_BYTES)
    {
        return Err("certified merge QC exceeds a hard count or byte limit".to_owned());
    }
    if qc.validator_set.len() != context.roster.len()
        || qc
            .validator_set
            .iter()
            .zip(&context.roster)
            .any(|(actual, expected)| actual != &expected.validator)
    {
        return Err("certified merge QC does not use the frozen height roster".to_owned());
    }
    Ok(())
}
fn authenticate_bounded_merge_sidecar_holders(
    context: &wire::HeightContext,
    reference: &CertifiedMergeLedgerReference,
) -> Result<Vec<PeerId>, String> {
    let qc = &reference.merge_qc;
    let holders = certified_merge_sidecar_holders(reference).map_err(|error| error.to_string())?;
    let mut signer_indices = Vec::with_capacity(holders.len());
    for (byte_index, byte) in qc.signers_bitmap.iter().copied().enumerate() {
        for bit in 0_u8..8 {
            if byte & (1_u8 << bit) != 0 {
                signer_indices.push(byte_index * 8 + usize::from(bit));
            }
        }
    }
    let validator_indices = signer_indices
        .iter()
        .map(|index| {
            u32::try_from(*index)
                .map_err(|_| "certified merge QC signer index exceeds u32".to_owned())
        })
        .collect::<Result<Vec<_>, _>>()?;
    context
        .validate_certificate_signers(&validator_indices)
        .map_err(|error| format!("certified merge QC has invalid signer cardinality: {error}"))?;
    if qc.signer_proofs.len() != signer_indices.len() {
        return Err("certified merge QC signer proofs do not match its bitmap".to_owned());
    }
    let mut public_keys = Vec::with_capacity(signer_indices.len());
    let mut proof_refs = Vec::with_capacity(signer_indices.len());
    for (index, proof) in signer_indices.iter().copied().zip(&qc.signer_proofs) {
        let expected_signer = u32::try_from(index)
            .map_err(|_| "certified merge QC signer index exceeds u32".to_owned())?;
        if proof.signer != expected_signer {
            return Err("certified merge QC signer proofs are not canonical".to_owned());
        }
        let public_key = qc
            .validator_set
            .get(index)
            .expect("validated signer index is in the exact frozen roster")
            .public_key();
        iroha_crypto::bls_normal_pop_verify(public_key, &proof.proof_of_possession)
            .map_err(|_| "certified merge QC contains an invalid proof of possession".to_owned())?;
        public_keys.push(public_key);
        proof_refs.push(proof.proof_of_possession.as_slice());
    }
    iroha_crypto::bls_normal_verify_preaggregated_same_message(
        qc.message_digest.as_ref(),
        &qc.aggregate_signature,
        &public_keys,
        &proof_refs,
    )
    .map_err(|_| "certified merge QC aggregate signature is invalid".to_owned())?;
    Ok(holders)
}
/// Authenticate a full merge entry against the exact frozen carrier context.
///
/// State owns deterministic entry/execution validation, but its replicated
/// commit topology does not retain the height context's voting powers. Every
/// production path therefore crosses this shared count-and-power verifier
/// before a local, fetched, replayed, or preseeded sidecar becomes carrier
/// eligible.
pub(crate) fn authenticate_merge_entry_for_height_context(
    context: &wire::HeightContext,
    entry: &MergeLedgerEntry,
) -> Result<(), String> {
    let reference = CertifiedMergeLedgerReference::new(entry);
    validate_merge_sidecar_reference_bounds(context, &reference)?;
    authenticate_bounded_merge_sidecar_holders(context, &reference)?;
    Ok(())
}
fn merge_entry_has_exact_carrier_binding(
    context: &wire::HeightContext,
    entry: &MergeLedgerEntry,
) -> bool {
    let expected_parent = context
        .parent_commit_qc
        .as_ref()
        .map(|certificate| certificate.subject.block_hash)
        .or_else(|| {
            context
                .snapshot_bootstrap
                .as_ref()
                .map(|anchor| anchor.snapshot_block_hash)
        });
    entry.merge_qc.carrier_height == context.height
        && expected_parent == Some(entry.merge_qc.carrier_parent_hash)
}
fn bounded_merge_qc_authentication_key(
    reference: &CertifiedMergeLedgerReference,
) -> Result<Hash, String> {
    let bytes = reference.merge_qc.encode();
    if bytes.len() > MAX_FETCH_MERGE_QC_BYTES {
        return Err("certified merge QC exceeds a hard count or byte limit".to_owned());
    }
    Ok(Hash::new_from_chunks(&[
        MERGE_QC_AUTH_CACHE_DOMAIN,
        bytes.as_slice(),
    ]))
}
/// Exact local bounds for one height-local lane/AMX adapter.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct V2LaneWorkLimits {
    session_capacity: NonZeroUsize,
    body_buckets_per_session: NonZeroUsize,
    native_session_capacity: NonZeroUsize,
    native_body_buckets_per_session: NonZeroUsize,
    native_source_capacity: NonZeroUsize,
    /// Ordinary effect owners; one additional autonomous NewView progress
    /// occurrence is reserved while such an occurrence is queued.
    effect_capacity: NonZeroUsize,
    relay_capacity: NonZeroUsize,
    merge_capacity: NonZeroUsize,
    native_request_capacity: NonZeroUsize,
    reply_source_capacity: NonZeroUsize,
    merge_share_frame_capacity: NonZeroUsize,
    historical_recovery_response_frame_capacity: NonZeroUsize,
    authenticated_merge_qc_capacity: NonZeroUsize,
    merge_leader_body_frame_headroom_bytes: NonZeroUsize,
    autonomous_carrier_headroom_bytes: NonZeroUsize,
    autonomous_producer_recheck: Duration,
    historical_recovery_retry_floor: Duration,
    historical_recovery_retry_ceiling: Duration,
    historical_recovery_stuck_attempts: NonZeroU32,
    historical_recovery_retry_tier_attempts: NonZeroU32,
    historical_recovery_max_retry_tier: NonZeroU32,
    sidecar_service_burst: NonZeroUsize,
    merge_sidecar_limits: MergeSidecarLimits,
    merge_signing_guard_limits: MergeSigningGuardLimits,
    native_amx_signing_guard_limits: NativeAmxSigningGuardLimits,
}
impl V2LaneWorkLimits {
    /// Construct non-zero bounds for every retained collection.
    pub(crate) fn new(
        session_capacity: NonZeroUsize,
        body_buckets_per_session: NonZeroUsize,
        effect_capacity: NonZeroUsize,
        relay_capacity: NonZeroUsize,
        merge_capacity: NonZeroUsize,
        native_request_capacity: NonZeroUsize,
        reply_source_capacity: NonZeroUsize,
        merge_share_frame_capacity: NonZeroUsize,
        historical_recovery_response_frame_capacity: NonZeroUsize,
        authenticated_merge_qc_capacity: NonZeroUsize,
        merge_leader_body_frame_headroom_bytes: NonZeroUsize,
        autonomous_carrier_headroom_bytes: NonZeroUsize,
        autonomous_producer_recheck: Duration,
        historical_recovery_retry_floor: Duration,
        historical_recovery_retry_ceiling: Duration,
        historical_recovery_stuck_attempts: NonZeroU32,
        historical_recovery_retry_tier_attempts: NonZeroU32,
        historical_recovery_max_retry_tier: NonZeroU32,
        sidecar_service_burst: NonZeroUsize,
        merge_sidecar_limits: MergeSidecarLimits,
        merge_signing_guard_limits: MergeSigningGuardLimits,
        native_amx_signing_guard_limits: NativeAmxSigningGuardLimits,
    ) -> Self {
        Self {
            session_capacity,
            body_buckets_per_session,
            native_session_capacity: session_capacity,
            native_body_buckets_per_session: body_buckets_per_session,
            native_source_capacity: body_buckets_per_session,
            effect_capacity,
            relay_capacity,
            merge_capacity,
            native_request_capacity,
            reply_source_capacity,
            merge_share_frame_capacity,
            historical_recovery_response_frame_capacity,
            authenticated_merge_qc_capacity,
            merge_leader_body_frame_headroom_bytes,
            autonomous_carrier_headroom_bytes,
            autonomous_producer_recheck,
            historical_recovery_retry_floor,
            historical_recovery_retry_ceiling,
            historical_recovery_stuck_attempts,
            historical_recovery_retry_tier_attempts,
            historical_recovery_max_retry_tier,
            sidecar_service_burst,
            merge_sidecar_limits,
            merge_signing_guard_limits,
            native_amx_signing_guard_limits,
        }
    }
    /// Override only Native-AMX cache geometry without widening unrelated lane owners.
    #[must_use]
    pub(crate) const fn with_native_cache_limits(
        mut self,
        native_session_capacity: NonZeroUsize,
        native_body_buckets_per_session: NonZeroUsize,
        native_source_capacity: NonZeroUsize,
    ) -> Self {
        self.native_session_capacity = native_session_capacity;
        self.native_body_buckets_per_session = native_body_buckets_per_session;
        self.native_source_capacity = native_source_capacity;
        self
    }
}
fn native_amx_signing_guard_capacity(
    limits: V2LaneWorkLimits,
) -> Result<NonZeroUsize, V2LaneWorkError> {
    Ok(limits.native_amx_signing_guard_limits.max_records)
}
/// Reserve every current-roster responder identity plus one complete
/// predecessor committee.
///
/// Height-context admission already proves `roster_len <=
/// MAX_VALIDATORS_PER_HEIGHT`, so the sum is bounded by the transport's
/// protocol-wide two-committee ceiling.
const fn merge_sidecar_server_stream_capacity(roster_len: usize) -> usize {
    roster_len + wire::MAX_VALIDATORS_PER_HEIGHT
}
/// One authenticated lane-local transport action emitted by the adapter.
#[derive(Clone, Debug)]
pub(crate) enum V2LaneWorkEffect {
    /// Send one canonical lane-local message to a committee member.
    PostLaneBlock {
        /// Destination committee member.
        peer: PeerId,
        /// Lane-local message; global legacy variants are never emitted.
        message: BlockMessage,
    },
    /// Send one exact certificate reconstructed from an immutable Kura lane artifact.
    PostDurableLaneCertificate {
        /// Authenticated requester of the durable certificate.
        peer: PeerId,
        /// Independent authenticated sources which delivered the idempotent request.
        reply_routes: Option<NetworkReplyRoutes>,
        /// Exact fair-ingress request ownership consumed by this response.
        ingress_ownership: Option<FairV2IngressOwnershipEvidence>,
        /// Exact proposal and Prepare/Commit QCs read from Kura.
        certificate: LaneBlockCertificateV1,
    },
    /// Send a context-bound Native AMX request or vote to one peer.
    PostNativeAmx {
        /// Destination participant/coordinator.
        peer: PeerId,
        /// Independent request sources for request-induced votes; absent for coordinator traffic.
        reply_routes: Option<NetworkReplyRoutes>,
        /// Context-bound Native AMX v2 message.
        message: NativeAmxMessage,
    },
    /// Send one exact durably authorized lane-drain vote to a lane/global peer.
    PostLaneDrainVote {
        /// Destination in the canonical lane/global committee union.
        peer: PeerId,
        /// Exact committee-signed drain frontier vote.
        vote: LaneDrainVoteV1,
    },
    /// Broadcast a merge signature share to the frozen voting roster.
    BroadcastMerge(MergeCommitteeSignature),
    /// Hand one exact Kura-durable QueuePlan admission certificate to the current leader.
    PostQueuePlanAdmissionCertificate {
        /// Current global leader selected by the frozen height context.
        peer: PeerId,
        /// Frozen global view which selected `peer` as leader.
        view: wire::View,
        /// Exact canonical quorum-certificate bytes.
        certificate: Arc<Vec<u8>>,
    },
    /// Send one authenticated certified merge-sidecar request or response.
    PostCertifiedMergeSidecar {
        /// Exact destination selected by the sidecar transport.
        peer: PeerId,
        /// Independent request sources for request-induced responses; absent
        /// for requester-owned Request and Close output.
        reply_routes: Option<NetworkReplyRoutes>,
        /// Bounded request or fixed-boundary response chunk.
        message: Arc<CertifiedMergeSidecarMessage>,
    },
}
impl V2LaneWorkEffect {
    /// Return whether adapter-owned catalog state can recreate this exact
    /// request after the worker declines ownership.
    ///
    /// Dropping only these source-retained effects frees the bounded adapter
    /// queue to rotate past a saturated or Byzantine peer. Votes and every
    /// other one-shot response still require exact effect requeueing.
    pub(crate) fn retries_from_native_catalog_after_source_retention(&self) -> bool {
        matches!(
            self,
            Self::PostNativeAmx {
                reply_routes: None,
                message: NativeAmxMessage::PrepareRequest(_) | NativeAmxMessage::CommitRequest(_),
                ..
            }
        )
    }
}
/// Result of registering an otherwise-valid body whose certified merge
/// sidecar is not yet present locally.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) enum MergeSidecarDeferralDisposition {
    /// A bounded authenticated fetch is active (or already active).
    Fetching,
    /// The exact entry was already durable and validation can retry now.
    Available,
    /// A transient bounded transport cap prevented registration; the caller
    /// must retain and retry the exact deferral.
    RetryLater,
    /// The compact reference cannot describe this body's exact carrier.
    Rejected(String),
}
