    fn fixture_at_height_inner_with_limits_and_kura_and_local_index(
        mode: wire::ConsensusMode,
        height: u64,
        persist_parent_chain: bool,
        limits: V2LaneWorkLimits,
        kura: Arc<Kura>,
        local_validator_index: Option<usize>,
        voting_enabled: bool,
    ) -> (V2LaneWorkAdapter, Vec<KeyPair>) {
        let chain_id: ChainId = "v2-lane-work-display-name".into();
        let network_id = crate::sumeragi::synthetic_network_id("v2-lane-work-test");
        let mut keys = (1_u8..=4)
            .map(|seed| {
                KeyPair::try_from_seed(vec![seed; 32], Algorithm::BlsNormal)
                    .expect("deterministic BLS key")
            })
            .collect::<Vec<_>>();
        keys.sort_by(|left, right| left.public_key().cmp(right.public_key()));
        let mut world = World::new();
        let mut peers = crate::Peers::default();
        for (index, key) in keys.iter().enumerate() {
            let peer_id = PeerId::new(key.public_key().clone());
            let _ = peers.push(peer_id);
            let id = ConsensusKeyId::new(ConsensusKeyRole::Validator, format!("validator{index}"));
            let record = ConsensusKeyRecord {
                id: id.clone(),
                public_key: key.public_key().clone(),
                pop: Some(
                    iroha_crypto::bls_normal_pop_prove(key.private_key())
                        .expect("BLS proof of possession"),
                ),
                activation_height: 0,
                expiry_height: None,
                hsm: None,
                replaces: None,
                status: ConsensusKeyStatus::Active,
            };
            world.consensus_keys.insert(id.clone(), record.clone());
            world
                .consensus_keys_by_pk
                .insert(record.public_key.to_string(), vec![id]);
        }
        world.peers = mv::cell::Cell::new(peers);
        if matches!(mode, wire::ConsensusMode::Npos) {
            let parameters = SumeragiNposParameters::default();
            parameters
                .validate()
                .expect("default lane-work NPoS parameters must be valid");
            let mut block = world.parameters.block();
            block.set_parameter(Parameter::Custom(parameters.into_custom_parameter()));
            block.commit();
        }
        let state = Arc::new(State::new_with_chain_and_network_id_for_testing(
            world,
            Arc::clone(&kura),
            LiveQueryStore::start_test(),
            chain_id,
            network_id,
        ));
        let npos_epoch_length = matches!(mode, wire::ConsensusMode::Npos).then(|| {
            SumeragiNposParameters::default()
                .epoch_length_blocks()
                .get()
        });
        let context_epoch = {
            let world = state.world_view();
            crate::sumeragi::epoch_for_height_from_world(&world, height, mode)
                .expect("lane-work fixture has an authenticated epoch schedule")
        };
        let context_epoch_end_height = npos_epoch_length.map_or(u64::MAX, |epoch_length| {
            context_epoch.saturating_add(1).saturating_mul(epoch_length)
        });
        let validators = keys
            .iter()
            .map(|key| AccountId::new(key.public_key().clone()))
            .collect::<Vec<_>>();
        let validator_bindings = validators
            .iter()
            .zip(&keys)
            .map(|(validator, key)| ManifestValidatorBinding {
                validator: validator.clone(),
                peer_id: PeerId::new(key.public_key().clone()),
                torii_url: None,
            })
            .collect();
        state.install_lane_manifests(&Arc::new(LaneManifestRegistry::from_statuses(
            BTreeMap::from([(
                LaneId::SINGLE,
                LaneManifestStatus {
                    lane: LaneId::SINGLE,
                    alias: "default".to_owned(),
                    dataspace: DataSpaceId::UNIVERSAL,
                    visibility: LaneVisibility::Public,
                    storage: LaneStorageProfile::FullReplica,
                    governance: Some("default-lane-governance".to_owned()),
                    manifest_path: Some(std::path::PathBuf::from(
                        "/tmp/v2-default-lane-manifest.json",
                    )),
                    governance_rules: Some(GovernanceRules {
                        validators,
                        validator_bindings,
                        ..GovernanceRules::default()
                    }),
                    privacy_commitments: Vec::new(),
                },
            )]),
        )));
        // NPoS stake selects the epoch committee; consensus remains one vote
        // per finalized committee member, just like permissioned mode.
        let powers = [1, 1, 1, 1];
        let roster = keys
            .iter()
            .zip(powers)
            .map(|(key, power)| wire::ValidatorPower {
                validator: PeerId::new(key.public_key().clone()),
                power,
            })
            .collect::<Vec<_>>();
        let mut context = wire::HeightContext {
            network_id,
            protocol_version: wire::PROTOCOL_VERSION,
            height,
            epoch: context_epoch,
            epoch_end_height: context_epoch_end_height,
            next_epoch_snapshot: None,
            mode,
            parent_commit_qc: (height > 1).then(|| wire::QuorumCertificate {
                round: wire::ConsensusRound {
                    context_id: wire::HeightContextId(HashOf::from_untyped_unchecked(Hash::new(
                        format!("v2-lane-work-parent-context:{}", height - 1).as_bytes(),
                    ))),
                    height: height - 1,
                    view: 0,
                },
                proposal_round: wire::ConsensusRound {
                    context_id: wire::HeightContextId(HashOf::from_untyped_unchecked(Hash::new(
                        format!("v2-lane-work-parent-context:{}", height - 1).as_bytes(),
                    ))),
                    height: height - 1,
                    view: 0,
                },
                phase: wire::GlobalPhase::Commit,
                subject: wire::BlockSubject {
                    parent_block_hash: None,
                    block_hash: HashOf::from_untyped_unchecked(Hash::new(
                        format!("v2-lane-work-parent-block:{}", height - 1).as_bytes(),
                    )),
                    payload_hash: Hash::new(
                        format!("v2-lane-work-parent-payload:{}", height - 1).as_bytes(),
                    ),
                },
                execution_commitment: wire::ExecutionCommitment::without_topups_or_merge_carrier(
                    Hash::new(b"lane-work parent state"),
                    Hash::new(b"lane-work post state"),
                    Hash::new(b"lane-work ordinary writes"),
                    1,
                    Hash::new(b"lane-work executed block wire"),
                ),
                signers: vec![0, 1, 2],
                aggregate_signature: vec![0xA5; 48],
            }),
            snapshot_bootstrap: None,
            quorum: wire::DualQuorum::from_roster(&roster).expect("dual quorum"),
            roster,
            nexus_amx_context_hash: super::super::v2_recovery::committed_nexus_amx_context_hash(
                state.as_ref(),
            ),
            execution_policy_hash: super::super::v2_recovery::committed_execution_policy_hash(
                state.as_ref(),
            )
            .expect("derive lane-work execution policy"),
            da_layout: wire::DataAvailabilityLayout {
                encoding: wire::PayloadEncoding::ReedSolomon16,
                chunk_size_bytes: 1024,
                data_shards: 1,
                parity_shards: 1,
                max_payload_size_bytes: 4096,
                max_chunk_count: 8,
            },
            leader_seed: [0x42; 32],
        };
        let mut parent = None;
        for block_height in 1..height {
            let valid = ValidBlock::new_dummy_and_modify_header(
                keys[0].private_key(),
                |header: &mut BlockHeader| {
                    header.set_height(
                        NonZeroU64::new(block_height).expect("non-zero fixture height"),
                    );
                    header.set_prev_block_hash(parent);
                    header.merkle_root = None;
                },
            );
            let block =
                commit_result_bearing_lane_parent(valid, state.as_ref(), keys[0].private_key());
            parent = Some(block.as_ref().hash());
            if persist_parent_chain {
                kura.store_block(block.clone())
                    .expect("persist exact merge-signing parent fixture");
            }
            commit_test_block_to_state(state.as_ref(), &block, &context);
        }
        if let Some(parent_qc) = context.parent_commit_qc.as_mut() {
            parent_qc.subject.block_hash = parent.expect("non-genesis fixture has a parent");
        }
        let local_index = local_validator_index
            .unwrap_or_else(|| usize::try_from(context.leader(0)).expect("leader index"));
        assert!(
            local_index < keys.len(),
            "local validator index is in bounds"
        );
        let local_key = keys[local_index].clone();
        let local_peer = PeerId::new(local_key.public_key().clone());
        let authenticated_genesis_nexus_amx_context = (height == 1).then(|| {
            AuthenticatedGenesisNexusAmxContext::Staged(StagedGenesisNexusAmxContext::for_test(
                context.nexus_amx_context_hash,
            ))
        });
        let adapter = V2LaneWorkAdapter::new_with_output_guard(
            context,
            local_peer,
            local_key,
            voting_enabled,
            state,
            kura,
            limits,
            authenticated_genesis_nexus_amx_context,
            None,
            ConsensusOutputGuard::isolated(),
        )
        .expect("open lane adapter");
        (adapter, keys)
    }
    fn enable_multilane_nexus(
        adapter: &mut V2LaneWorkAdapter,
        keys: &[KeyPair],
        lane_id: LaneId,
        dataspace_id: DataSpaceId,
    ) -> Vec<PeerId> {
        let_row! { lane_catalog = LaneCatalog::new( NonZeroU32::new(2).expect("non-zero lane count"), vec![ LaneConfig::default(), LaneConfig { id: lane_id, dataspace_id, alias: "independent-lane".to_owned(), ..LaneConfig::default() }, ], ) .expect("multi-lane test catalog") };
        let_row! { dataspace_catalog = DataSpaceCatalog::new(vec![ DataSpaceMetadata::default(), DataSpaceMetadata { id: dataspace_id, alias: "independent-dataspace".to_owned(), description: None, fault_tolerance: 1, }, ]) .expect("multi-lane test dataspace catalog") };
        {
            let mut nexus = adapter.state.nexus.write();
            nexus.lane_config =
                iroha_config::parameters::actual::LaneConfig::from_catalog(&lane_catalog);
            nexus.lane_catalog = lane_catalog;
            nexus.dataspace_catalog = dataspace_catalog;
        }
        adapter.state.reseed_static_lane_incarnations_for_tests();
        let mut world_block = adapter.state.world.block();
        {
            let mut peers = world_block.peers_mut_for_testing().transaction();
            for key in keys {
                let peer = PeerId::new(key.public_key().clone());
                if !peers.iter().any(|existing| existing == &peer) {
                    peers.push(peer);
                }
            }
            peers.apply();
        }
        world_block.commit();
        let_row! { validators = keys .iter() .map(|key| AccountId::new(key.public_key().clone())) .collect::<Vec<_>>() };
        let_row! { validator_bindings = validators .iter() .zip(keys) .map(|(validator, key)| ManifestValidatorBinding { validator: validator.clone(), peer_id: PeerId::new(key.public_key().clone()), torii_url: None, }) .collect::<Vec<_>>() };
        let_row! { default_status = LaneManifestStatus { lane: LaneId::SINGLE, alias: "default".to_owned(), dataspace: DataSpaceId::UNIVERSAL, visibility: LaneVisibility::Public, storage: LaneStorageProfile::FullReplica, governance: Some("default-lane-governance".to_owned()), manifest_path: Some(std::path::PathBuf::from("/tmp/v2-default-lane-manifest.json")), governance_rules: Some(GovernanceRules { validators: validators.clone(), validator_bindings: validator_bindings.clone(), ..GovernanceRules::default() }), privacy_commitments: Vec::new(), } };
        let status = LaneManifestStatus {
            lane: lane_id,
            alias: "independent-lane".to_owned(),
            dataspace: dataspace_id,
            visibility: LaneVisibility::Public,
            storage: LaneStorageProfile::FullReplica,
            governance: Some("independent-lane-governance".to_owned()),
            manifest_path: Some(std::path::PathBuf::from(
                "/tmp/v2-independent-lane-manifest.json",
            )),
            governance_rules: Some(GovernanceRules {
                validators,
                validator_bindings,
                ..GovernanceRules::default()
            }),
            privacy_commitments: Vec::new(),
        };
        adapter
            .state
            .install_lane_manifests(&Arc::new(LaneManifestRegistry::from_statuses(
                BTreeMap::from([(LaneId::SINGLE, default_status), (lane_id, status)]),
            )));
        adapter.context.nexus_amx_context_hash =
            super::super::v2_recovery::committed_nexus_amx_context_hash(adapter.state.as_ref());
        adapter.context.execution_policy_hash =
            super::super::v2_recovery::committed_execution_policy_hash(adapter.state.as_ref())
                .expect("derive multi-lane test execution policy");
        assert!(proposal_lookahead_enabled(
            &adapter.state.nexus_snapshot(),
            adapter.context.height,
        ));
        let mut validators = adapter
            .state
            .resolve_lane_committee_at_height(
                crate::state::LaneAuthorityRoute::new(lane_id, dataspace_id),
                adapter.context.height,
            )
            .expect("multi-lane fixture authority must resolve")
            .into_validators();
        validators.sort();
        validators.dedup();
        assert_eq!(validators.len(), keys.len());
        validators
    }
    fn enable_single_custom_lane_nexus(
        adapter: &mut V2LaneWorkAdapter,
        keys: &[KeyPair],
        lane_id: LaneId,
        dataspace_id: DataSpaceId,
    ) -> Vec<PeerId> {
        let validators = enable_multilane_nexus(adapter, keys, lane_id, dataspace_id);
        let_row! { lane_count = lane_id .as_u32() .checked_add(1) .and_then(NonZeroU32::new) .expect("custom lane id must fit its non-zero catalog bound") };
        let_row! { lane_catalog = LaneCatalog::new( lane_count, vec![LaneConfig { id: lane_id, dataspace_id, alias: "independent-lane".to_owned(), ..LaneConfig::default() }], ) .expect("single custom-lane test catalog") };
        let_row! { dataspace_catalog = DataSpaceCatalog::new(vec![DataSpaceMetadata { id: dataspace_id, alias: "independent-dataspace".to_owned(), description: None, fault_tolerance: 1, }]) .expect("single custom-dataspace test catalog") };
        stmt_row! { { let mut nexus = adapter.state.nexus.write(); nexus.routing_policy = iroha_config::parameters::actual::LaneRoutingPolicy { default_lane: lane_id, default_dataspace: dataspace_id, rules: Vec::new(), }; nexus.lane_config = iroha_config::parameters::actual::LaneConfig::from_catalog(&lane_catalog); nexus.lane_catalog = lane_catalog; nexus.dataspace_catalog = dataspace_catalog; } }
        adapter.state.reseed_static_lane_incarnations_for_tests();
        stmt_row! { adapter.context.nexus_amx_context_hash = super::super::v2_recovery::committed_nexus_amx_context_hash(adapter.state.as_ref()); }
        stmt_row! { adapter.context.execution_policy_hash = super::super::v2_recovery::committed_execution_policy_hash(adapter.state.as_ref()).expect("derive single custom-lane test execution policy"); }
        stmt_row! { assert!(!proposal_lookahead_enabled(&adapter.state.nexus_snapshot(), adapter.context.height,), "one custom route must retain the narrow proposal scan"); }
        stmt_row! { assert_eq!(adapter.state.consensus_lane_routes_at_height(adapter.context.height).into_keys().collect::<Vec<_>>(), vec![(lane_id, dataspace_id)], "fixture must expose exactly one enabled custom route"); }
        stmt_row! { assert_eq!(adapter.state.resolve_lane_committee_at_height(crate::state::LaneAuthorityRoute::new(lane_id, dataspace_id), adapter.context.height).expect("single custom-lane authority must resolve").into_validators(), validators, "narrowing routing must preserve the custom lane authority"); }
        validators
    }
    #[test]
    fn enabled_single_custom_lane_uses_rotating_lane_author_for_attached_proposal() {
        let_row! { (mut adapter, keys) = fixture(wire::ConsensusMode::Permissioned) };
        let lane_id = LaneId::new(1);
        let dataspace_id = DataSpaceId::new(7);
        let_row! { validators = enable_single_custom_lane_nexus(&mut adapter, &keys, lane_id, dataspace_id) };
        let_row! { global_leader = usize::try_from(adapter.context.leader(0)) .ok() .and_then(|index| adapter.context.roster.get(index)) .map(|entry| entry.validator.clone()) .expect("fixture global leader") };
        let validator_count = u64::try_from(validators.len()).expect("validator count fits u64");
        let_row! { lane_block_height = (1..=validator_count) .find(|height| deterministic_lane_author(&validators, *height) != Some(&global_leader)) .expect("rotating lane authority differs from the global leader in one cycle") };
        let_row! { lane_incarnation = adapter .state .lane_incarnation_at_height(lane_id, adapter.context.height) .expect("active custom-lane incarnation") };
        let_row! { proposal = proposal_for_route( &adapter, &keys, lane_id, dataspace_id, lane_incarnation, adapter.context.height, lane_block_height, ) };
        let_row! { lane_author = deterministic_lane_author(&validators, lane_block_height) .cloned() .expect("deterministic custom-lane author") };
        stmt_row! { assert_eq!(adapter.expected_lane_validators(lane_id, dataspace_id, adapter.context.height), Some(validators)); }
        stmt_row! { assert_eq!(adapter.expected_lane_author(&proposal), Some(&lane_author)); }
        stmt_row! { assert_ne!(lane_author, global_leader); }
    }
    fn limits_with_native_capacity(record_capacity: usize) -> V2LaneWorkLimits {
        let one = NonZeroUsize::new(1).expect("non-zero fixture limit");
        let record_capacity =
            NonZeroUsize::new(record_capacity).expect("non-zero signing-record capacity");
        V2LaneWorkLimits::new(
            one,
            one,
            one,
            one,
            one,
            one,
            one,
            iroha_config::parameters::defaults::network::MAX_FRAME_BYTES_CONSENSUS,
            iroha_config::parameters::defaults::network::MAX_FRAME_BYTES_BLOCK_SYNC,
            iroha_config::parameters::defaults::sumeragi::V2_AUTHENTICATED_MERGE_QC_CAPACITY,
            iroha_config::parameters::defaults::sumeragi::V2_MERGE_LEADER_BODY_FRAME_HEADROOM_BYTES,
            iroha_config::parameters::defaults::sumeragi::V2_AUTONOMOUS_CARRIER_HEADROOM_BYTES,
            iroha_config::parameters::defaults::sumeragi::V2_AUTONOMOUS_PRODUCER_RECHECK,
            Duration::from_millis(10),
            Duration::from_secs(1),
            iroha_config::parameters::defaults::sumeragi::V2_HISTORICAL_RECOVERY_STUCK_ATTEMPTS,
            iroha_config::parameters::defaults::sumeragi::V2_HISTORICAL_RECOVERY_RETRY_TIER_ATTEMPTS,
            iroha_config::parameters::defaults::sumeragi::V2_HISTORICAL_RECOVERY_MAX_RETRY_TIER,
            iroha_config::parameters::defaults::sumeragi::V2_SIDECAR_SERVICE_BURST,
            MergeSidecarLimits::defaults(),
            MergeSigningGuardLimits::defaults(),
            NativeAmxSigningGuardLimits::new(
                record_capacity,
                iroha_config::parameters::defaults::sumeragi::V2_NATIVE_AMX_SIGNING_GUARD_RECORD_BYTES,
                iroha_config::parameters::defaults::sumeragi::V2_NATIVE_AMX_SIGNING_GUARD_ANCHOR_BYTES,
            )
            .expect("valid explicit Native AMX signing limits"),
        )
    }
    #[test]
    fn merge_carrier_context_header_is_deterministic_and_view_scoped() {
        let (adapter, _) = fixture_with_durable_parent(wire::ConsensusMode::Permissioned);
        let view_zero = adapter
            .merge_carrier_context_header(0)
            .expect("derive exact view-zero carrier context");
        assert_eq!(
            adapter
                .merge_carrier_context_header(0)
                .expect("exact retry is deterministic"),
            view_zero
        );
        let parent_height = NonZeroUsize::new(adapter.state.committed_height())
            .expect("non-genesis fixture has a parent");
        let parent = adapter
            .kura
            .get_block(parent_height)
            .expect("fixture persisted the exact parent");
        let logical_time = parent
            .header()
            .creation_time()
            .checked_add(adapter.state.sumeragi_block_cadence())
            .expect("fixture carrier timestamp");
        let (_, time_source) = iroha_primitives::time::TimeSource::new_mock(logical_time);
        let rebuilt = crate::block::BlockBuilder::new_with_time_source(Vec::new(), time_source)
            .chain(0, Some(parent.as_ref()))
            .carrier_context_header();
        assert_eq!(view_zero, rebuilt);
        assert_eq!(view_zero.merkle_root(), None);
        assert_eq!(view_zero.result_merkle_root(), None);
        let view_three = adapter
            .merge_carrier_context_header(3)
            .expect("derive exact higher-view carrier context");
        assert_eq!(view_three.height(), view_zero.height());
        assert_eq!(view_three.prev_block_hash(), view_zero.prev_block_hash());
        assert_eq!(view_three.creation_time(), view_zero.creation_time());
        assert_eq!(view_three.view_change_index(), 3);
        assert_ne!(view_three, view_zero);
    }
    #[test]
    fn lane_drain_blocks_until_one_stable_live_queue_is_installed() {
        let (mut adapter, keys) = fixture(wire::ConsensusMode::Permissioned);
        let validator_set = keys
            .iter()
            .map(|key| PeerId::new(key.public_key().clone()))
            .collect::<Vec<_>>();
        let body = LaneDrainCertificateBodyV1 {
            version: 1,
            intent: iroha_data_model::merge::LaneDrainIntentV1 {
                version: 1,
                network_id: adapter.context.network_id,
                lane_id: LaneId::new(7),
                dataspace_id: DataSpaceId::new(9),
                lane_incarnation: Hash::new(b"adapter-drain-queue-incarnation"),
                close_global_height: adapter.context.height.saturating_sub(1),
                initial_frontier: iroha_data_model::merge::LaneDrainFrontierV1::ordinary(
                    LaneId::new(7),
                    DataSpaceId::new(9),
                    Hash::new(b"adapter-drain-queue-incarnation"),
                    0,
                    None,
                ),
                validator_set_hash_version: VALIDATOR_SET_HASH_VERSION_V1,
                validator_set_hash: HashOf::new(&validator_set),
                validator_count: u32::try_from(validator_set.len())
                    .expect("fixture committee count fits u32"),
                min_quorum: u32::try_from(
                    crate::sumeragi::network_topology::commit_quorum_from_len(validator_set.len()),
                )
                .expect("fixture drain quorum fits u32"),
                validator_set,
            },
            final_frontier: iroha_data_model::merge::LaneDrainFrontierV1::ordinary(
                LaneId::new(7),
                DataSpaceId::new(9),
                Hash::new(b"adapter-drain-queue-incarnation"),
                0,
                None,
            ),
        };
        assert!(
            adapter.lane_drain_has_local_blockers(&body),
            "missing production queue source must fail closed"
        );
        let queue = Arc::new(Queue::test(
            iroha_config::parameters::actual::Queue::default(),
            &iroha_primitives::time::TimeSource::new_system(),
        ));
        adapter
            .install_lane_drain_queue(Arc::clone(&queue))
            .expect("install the production queue blocker source");
        assert!(
            !adapter.lane_drain_has_local_blockers(&body),
            "an empty stable queue plus empty lane caches is drainable"
        );
        adapter.admitted_relays.insert((
            body.intent.lane_id,
            body.intent.dataspace_id,
            Hash::new(b"retired adapter-drain relay incarnation"),
            1,
            Hash::new(b"retired adapter-drain relay settlement"),
        ));
        assert!(
            !adapter.lane_drain_has_local_blockers(&body),
            "incarnation-A relay cache evidence must not ABA-block incarnation B"
        );
        adapter.admitted_relays.insert((
            body.intent.lane_id,
            body.intent.dataspace_id,
            body.intent.lane_incarnation,
            1,
            Hash::new(b"active adapter-drain relay settlement"),
        ));
        assert!(
            adapter.lane_drain_has_local_blockers(&body),
            "an admitted relay for the exact incarnation remains a drain blocker"
        );
        adapter.admitted_relays.clear();
        assert!(!adapter.lane_drain_has_local_blockers(&body));
        adapter
            .install_lane_drain_queue(Arc::clone(&queue))
            .expect("reinstalling the identical queue is idempotent");
        let replacement = Arc::new(Queue::test(
            iroha_config::parameters::actual::Queue::default(),
            &iroha_primitives::time::TimeSource::new_system(),
        ));
        assert!(matches!(
            adapter.install_lane_drain_queue(replacement),
            Err(V2LaneWorkError::InvalidContext(_))
        ));
    }
    #[test]
    fn lane_commit_and_drain_signatures_share_one_durable_bidirectional_fence() {
        let drain_body_for = |adapter: &V2LaneWorkAdapter, proposal: &LaneBlockProposalV1| {
            let descriptor = &proposal.descriptor;
            LaneDrainCertificateBodyV1 {
                version: 1,
                intent: iroha_data_model::merge::LaneDrainIntentV1 {
                    version: 1,
                    network_id: adapter.context.network_id,
                    lane_id: descriptor.lane_id,
                    dataspace_id: descriptor.dataspace_id,
                    lane_incarnation: descriptor.lane_incarnation,
                    close_global_height: adapter.context.height.saturating_sub(1),
                    initial_frontier: iroha_data_model::merge::LaneDrainFrontierV1::ordinary(
                        descriptor.lane_id,
                        descriptor.dataspace_id,
                        descriptor.lane_incarnation,
                        0,
                        None,
                    ),
                    validator_set_hash_version: VALIDATOR_SET_HASH_VERSION_V1,
                    validator_set_hash: HashOf::new(&descriptor.validator_set),
                    validator_set: descriptor.validator_set.clone(),
                    validator_count: descriptor.validator_count,
                    min_quorum: descriptor.min_quorum,
                },
                final_frontier: iroha_data_model::merge::LaneDrainFrontierV1::ordinary(
                    descriptor.lane_id,
                    descriptor.dataspace_id,
                    descriptor.lane_incarnation,
                    0,
                    None,
                ),
            }
        };
        let (mut commit_first, keys) = fixture(wire::ConsensusMode::Permissioned);
        let incarnation = commit_first
            .state
            .lane_incarnation_at_height(LaneId::SINGLE, commit_first.context.height)
            .expect("fixture lane incarnation");
        let proposal = proposal_for_route(
            &commit_first,
            &keys,
            LaneId::SINGLE,
            DataSpaceId::UNIVERSAL,
            incarnation,
            commit_first.context.height,
            1,
        );
        commit_first
            .sign_lane_vote(&proposal, CertPhase::Commit)
            .expect("first Commit signing should not fail")
            .expect("first Commit crosses the durable signing fence");
        let drain_body = drain_body_for(&commit_first, &proposal);
        let committee = proposal.descriptor.validator_set.clone();
        assert!(matches!(
            commit_first.authorize_and_insert_local_lane_drain_vote(&drain_body, &committee),
            Err(V2LaneWorkError::SigningGuard(message))
                if message.contains("frontier does not cover")
        ));
        assert!(
            commit_first.output_guard.restart_required(),
            "a rejected drain signing boundary must fail-stop later output"
        );
        let (mut drain_first, keys) = fixture(wire::ConsensusMode::Permissioned);
        let incarnation = drain_first
            .state
            .lane_incarnation_at_height(LaneId::SINGLE, drain_first.context.height)
            .expect("fixture lane incarnation");
        let proposal = proposal_for_route(
            &drain_first,
            &keys,
            LaneId::SINGLE,
            DataSpaceId::UNIVERSAL,
            incarnation,
            drain_first.context.height,
            1,
        );
        let drain_body = drain_body_for(&drain_first, &proposal);
        let committee = proposal.descriptor.validator_set.clone();
        drain_first
            .lane_drain_votes
            .retain_body(Some(drain_body.clone()));
        drain_first
            .authorize_and_insert_local_lane_drain_vote(&drain_body, &committee)
            .expect("drain crosses the shared durable signing fence");
        assert!(
            drain_first
                .sign_lane_vote(&proposal, CertPhase::Commit)
                .expect("drain-conflicting Commit check should not fail")
                .is_none(),
            "a later Commit must not coexist with a durable drain decision"
        );
        assert!(
            drain_first.output_guard.restart_required(),
            "a Commit rejected by the durable drain fence must fail-stop later output"
        );
    }
