    #[test]
    fn stale_generation_hint_bypasses_obstructed_journal_without_latching_restart() {
        let CertifiedSidecarServerFixture {
            mut adapter,
            requester,
            request,
            ..
        } = certified_sidecar_server_fixture();
        let changed_roster = changed_merge_sidecar_server_roster();
        adapter
            .transition_merge_sidecar_responder_roster_for_test(&changed_roster)
            .expect("persist a quiescent successor responder generation");
        adapter
            .merge_sidecars
            .obstruct_lifecycle_journal_temp_for_test();
        let hub = PeerId::new(KeyPair::random().public_key().clone());
        let mut routes = NetworkReplyRouteTestFixture::with_source_capacity(
            hub.clone(),
            adapter.limits.reply_source_capacity.get(),
        );
        let output_guard = Arc::clone(&adapter.output_guard);
        let mut remote_requesters = vec![requester.clone()];
        remote_requesters.extend(
            adapter
                .context
                .roster
                .iter()
                .map(|entry| entry.validator.clone())
                .filter(|peer| peer != &adapter.local_peer && peer != &requester),
        );
        adapter.limits.relay_capacity =
            NonZeroUsize::new(remote_requesters.len()).expect("fixture has remote validators");
        let effect_capacity = adapter.limits.relay_capacity.get();
        for sender in &remote_requesters {
            let mut candidate = request.clone();
            candidate.requester = sender.clone();
            candidate.request_id = candidate.canonical_request_id();
            let reply_route = routes.mint_via(sender.clone(), hub.clone());
            assert_eq!(
                adapter
                    .accept_certified_merge_sidecar_for_test(
                        sender.clone(),
                        reply_route,
                        candidate,
                    )
                    .expect("a stale request returns its stateless generation Hint"),
                V2LaneIngressOutcome::Inserted
            );
        }
        let mut second_request = request.clone();
        second_request.semantic_sequence = semantic_sequence(
            second_request
                .semantic_sequence
                .get()
                .checked_add(1)
                .expect("the stale stream has a second occurrence"),
        );
        second_request.request_id = second_request.canonical_request_id();
        let full_queue_route = routes.mint_via(requester.clone(), hub.clone());
        assert_eq!(
            adapter
                .accept_certified_merge_sidecar_for_test(
                    requester.clone(),
                    full_queue_route,
                    second_request,
                )
                .expect("the full responder-control corridor remains nonfatal"),
            V2LaneIngressOutcome::Duplicate,
            "one roster requester cannot occupy a second responder-control slot"
        );
        assert!(!output_guard.restart_required());
        assert!(output_guard.acquire().is_some());
        assert_eq!(adapter.sidecar_effects.len(), effect_capacity);
        assert!(adapter.sidecar_effects.iter().any(|effect| {
            matches!(
                effect,
                V2LaneWorkEffect::PostCertifiedMergeSidecar {
                    reply_routes: Some(_),
                    message,
                    ..
                } if matches!(
                    message.as_ref(),
                    CertifiedMergeSidecarMessage::GenerationHint(hint)
                        if hint.observed_generation == request.service_generation
                            && hint.observed_message_hash
                                == HashOf::new(&request).into()
                    )
            )
        }));
        let mut close = CertifiedMergeSidecarCloseV1 {
            version: CERTIFIED_MERGE_SIDECAR_VERSION_V1,
            service_generation: request.service_generation,
            stream_epoch: request.stream_epoch,
            closed_through: request.semantic_sequence.get(),
            close_id: Hash::prehashed([0; Hash::LENGTH]),
            requester: requester.clone(),
            responder: adapter.local_peer.clone(),
        };
        close.close_id = close.canonical_close_id();
        let close_hash: Hash = HashOf::new(&close).into();
        let full_queue_reply_route = routes.mint_via(requester.clone(), hub.clone());
        assert_eq!(
            adapter.accept_relay_message(
                LaneRelayMessage::CertifiedMergeSidecar {
                    sender: requester.clone(),
                    reply_route: Some(full_queue_reply_route),
                    message: CertifiedMergeSidecarMessage::Close(close.clone()),
                },
                0,
            ),
            V2LaneIngressOutcome::Duplicate,
            "a full queue may drop a retryable stale-Close Hint without fail-stop"
        );
        assert!(!output_guard.restart_required());
        assert_eq!(adapter.sidecar_effects.len(), effect_capacity);
        assert_eq!(adapter.drain_effects(1).len(), 1);
        let replay_reply_route = routes.mint_via(requester.clone(), hub);
        assert_eq!(
            adapter.accept_relay_message(
                LaneRelayMessage::CertifiedMergeSidecar {
                    sender: requester,
                    reply_route: Some(replay_reply_route.clone()),
                    message: CertifiedMergeSidecarMessage::Close(close),
                },
                0,
            ),
            V2LaneIngressOutcome::Inserted,
            "replay after queue capacity returns the same durable generation fence"
        );
        assert!(adapter.sidecar_effects.iter().any(|effect| {
            matches!(
                effect,
                V2LaneWorkEffect::PostCertifiedMergeSidecar {
                    reply_routes: Some(reply_routes),
                    message,
                    ..
                } if matches!(
                    message.as_ref(),
                    CertifiedMergeSidecarMessage::GenerationHint(hint)
                        if hint.observed_generation == request.service_generation
                            && hint.observed_message_hash == close_hash
                ) && reply_routes
                    .iter()
                    .any(|route| route.same_delivery(&replay_reply_route))
            )
        }));
        assert!(!output_guard.restart_required());
    }
    #[test]
    fn stranded_responder_control_queue_slot_replaces_with_a_writable_trigger() {
        let CertifiedSidecarServerFixture {
            mut adapter,
            requester,
            request,
            ..
        } = certified_sidecar_server_fixture();
        let changed_roster = changed_merge_sidecar_server_roster();
        adapter
            .transition_merge_sidecar_responder_roster_for_test(&changed_roster)
            .expect("persist a quiescent successor responder generation");
        let hub_a = PeerId::new(KeyPair::random().public_key().clone());
        let hub_b = PeerId::new(KeyPair::random().public_key().clone());
        let hub_c = PeerId::new(KeyPair::random().public_key().clone());
        let hub_d = PeerId::new(KeyPair::random().public_key().clone());
        let mut routes = NetworkReplyRouteTestFixture::with_source_capacity(hub_a.clone(), 1);
        let route_a = routes.mint_via(requester.clone(), hub_a);
        assert_eq!(
            adapter
                .accept_certified_merge_sidecar_for_test(
                    requester.clone(),
                    route_a.clone(),
                    request.clone(),
                )
                .expect("the first stale request creates one generation Hint"),
            V2LaneIngressOutcome::Inserted
        );
        let other_requester = adapter
            .context
            .roster
            .iter()
            .map(|entry| entry.validator.clone())
            .find(|peer| peer != &adapter.local_peer && peer != &requester)
            .expect("the four-validator fixture has another remote requester");
        let mut other_request = request.clone();
        other_request.requester = other_requester.clone();
        other_request.request_id = other_request.canonical_request_id();
        let other_route = routes.mint_via(other_requester.clone(), hub_d);
        assert_eq!(
            adapter
                .accept_certified_merge_sidecar_for_test(
                    other_requester.clone(),
                    other_route,
                    other_request,
                )
                .expect("an independent target owns the next queue position"),
            V2LaneIngressOutcome::Inserted
        );
        assert!(
            routes.mark_reply_unwritable_while_delivery_active(&route_a),
            "the first exact return route starts draining"
        );
        let route_b = routes.mint_via(requester.clone(), hub_b);
        assert_eq!(
            adapter
                .accept_certified_merge_sidecar_for_test(
                    requester.clone(),
                    route_b.clone(),
                    request.clone(),
                )
                .expect("an exact replay replaces the stranded unwritable attempt"),
            V2LaneIngressOutcome::Inserted
        );
        assert_eq!(adapter.sidecar_effects.len(), 2);
        assert_eq!(adapter.sidecar_effect_keys.len(), 2);
        assert_eq!(
            retryable_sidecar_server_control_peer(
                adapter
                    .sidecar_effects
                    .front()
                    .expect("the independent control keeps its older queue age")
            ),
            Some(&other_requester),
            "the replacement must rejoin at the tail"
        );
        assert!(matches!(
            adapter.sidecar_effects.back(),
            Some(V2LaneWorkEffect::PostCertifiedMergeSidecar {
                reply_routes: Some(reply_routes),
                ..
            }) if reply_routes.len() == 1
                && reply_routes
                    .iter()
                    .any(|route| route.same_delivery(&route_b))
                && !reply_routes
                    .iter()
                    .any(|route| route.same_delivery(&route_a))
        ));
        assert!(
            routes.mark_reply_unwritable_while_delivery_active(&route_b),
            "the replacement exact route may independently start draining"
        );
        let mut later_request = request.clone();
        later_request.semantic_sequence = semantic_sequence(
            later_request
                .semantic_sequence
                .get()
                .checked_add(1)
                .expect("the stale stream has one later request"),
        );
        later_request.request_id = later_request.canonical_request_id();
        let later_request_hash: Hash = HashOf::new(&later_request).into();
        let route_c = routes.mint_via(requester.clone(), hub_c);
        assert_eq!(
            adapter
                .accept_certified_merge_sidecar_for_test(
                    requester.clone(),
                    route_c.clone(),
                    later_request,
                )
                .expect("a distinct live trigger replaces the stranded Hint"),
            V2LaneIngressOutcome::Inserted
        );
        assert_eq!(adapter.sidecar_effects.len(), 2);
        assert_eq!(adapter.sidecar_effect_keys.len(), 2);
        assert!(matches!(
            adapter.sidecar_effects.back(),
            Some(V2LaneWorkEffect::PostCertifiedMergeSidecar {
                peer,
                reply_routes: Some(reply_routes),
                message,
            }) if peer == &requester
                && reply_routes.len() == 1
                && reply_routes
                    .iter()
                    .any(|route| route.same_delivery(&route_c))
                && matches!(
                    message.as_ref(),
                    CertifiedMergeSidecarMessage::GenerationHint(hint)
                        if hint.observed_message_hash == later_request_hash
                )
        ));
        assert!(!adapter.output_guard.restart_required());
    }
