    #[test]
    fn durable_lane_certificate_is_one_atomic_kura_backed_response() {
        let (mut adapter, keys) = fixture_at_height(wire::ConsensusMode::Permissioned, 1);
        let (_, proposal) = globally_anchored_lane_block_fixture(&adapter, &keys);
        let session = committed_lane_session(&proposal, &keys);
        let pops = adapter.pops_for_lane_session(&session);
        adapter
            .kura
            .persist_committed_lane_block_session(&session, &pops)
            .expect("persist the authoritative recovery source");
        adapter.effects.clear();
        adapter.effect_keys.clear();
        adapter.lane_sessions = LaneBlockSessionCache::new(adapter.limits.session_capacity.get());
        let requester = session
            .commit_qc
            .validator_set
            .iter()
            .find(|peer| *peer != &adapter.local_peer)
            .cloned()
            .expect("fixture has a remote committee member");
        assert_eq!(
            accept_lane_message_from(
                &mut adapter,
                BlockMessage::LaneBlockProposal(proposal.clone()),
                requester.clone(),
                0,
            ),
            V2LaneIngressOutcome::Rejected,
            "a durable response must never fall back to topology without an exact request route"
        );
        assert!(adapter.drain_effects(usize::MAX).is_empty());
        let relay = PeerId::new(
            KeyPair::try_from_seed(vec![0xD6; 32], Algorithm::BlsNormal)
                .expect("relay key")
                .public_key()
                .clone(),
        );
        assert_ne!(relay, requester);
        let mut routes = NetworkReplyRouteTestFixture::new(relay.clone());
        let cancelled_route = routes.mint(requester.clone());
        assert!(routes.retire(&cancelled_route));
        assert!(matches!(
            InboundBlockMessage::try_from_transport_with_reply_route(
                BlockMessage::LaneBlockProposal(proposal.clone()),
                requester.clone(),
                relay.clone(),
                cancelled_route,
            ),
            Err(NetworkReplyRouteError::Inactive)
        ));
        assert!(adapter.drain_effects(usize::MAX).is_empty());
        let reply_route = routes.mint(requester.clone());
        assert_eq!(
            adapter.accept_lane_message(
                InboundBlockMessage::try_from_transport_with_reply_route(
                    BlockMessage::LaneBlockProposal(proposal.clone()),
                    requester.clone(),
                    relay,
                    reply_route.clone(),
                )
                .expect("active durable request route"),
                0,
            ),
            V2LaneIngressOutcome::Inserted
        );
        let effects = adapter.drain_effects(usize::MAX);
        assert_eq!(
            effects.len(),
            1,
            "Prepare and Commit must cross one owner boundary"
        );
        assert!(matches!(
            &effects[0],
            V2LaneWorkEffect::PostDurableLaneCertificate {
                peer,
                reply_routes: Some(emitted_routes),
                certificate,
                ..
            } if peer == &requester
                && emitted_routes.len() == 1
                && emitted_routes
                    .iter()
                    .any(|emitted_route| emitted_route.same_delivery(&reply_route))
                && certificate.proposal == session.proposal
                && certificate.prepare_qc == session.prepare_qc
                && certificate.commit_qc == session.commit_qc
        ));
    }
    #[test]
    fn durable_lane_certificate_coalescing_preserves_alternate_ingress_owners() {
        let (mut adapter, keys) = fixture_at_height(wire::ConsensusMode::Permissioned, 1);
        let (_, proposal) = globally_anchored_lane_block_fixture(&adapter, &keys);
        let session = committed_lane_session(&proposal, &keys);
        let pops = adapter.pops_for_lane_session(&session);
        adapter
            .kura
            .persist_committed_lane_block_session(&session, &pops)
            .expect("persist the authoritative recovery source");
        adapter.effects.clear();
        adapter.effect_keys.clear();
        adapter.lane_sessions = LaneBlockSessionCache::new(adapter.limits.session_capacity.get());
        let requester = session
            .commit_qc
            .validator_set
            .iter()
            .find(|peer| *peer != &adapter.local_peer)
            .cloned()
            .expect("fixture has a remote committee member");
        let hub_a = PeerId::new(KeyPair::random().public_key().clone());
        let hub_b = PeerId::new(KeyPair::random().public_key().clone());
        let mut route_fixture =
            NetworkReplyRouteTestFixture::with_source_capacity(hub_a.clone(), 2);
        let route_a = route_fixture.mint_via(requester.clone(), hub_a.clone());
        let route_b = route_fixture.mint_via(requester.clone(), hub_b.clone());
        let admitted = |via: PeerId, route: NetworkReplyRoute| {
            fair_v2_ingress_admit_for_test(
                InboundBlockMessage::try_from_transport_with_reply_route(
                    BlockMessage::LaneBlockProposal(proposal.clone()),
                    requester.clone(),
                    via,
                    route,
                )
                .expect("durable request route is exact"),
            )
        };
        assert_eq!(
            adapter.accept_lane_message_with_ingress_ownership(admitted(hub_a, route_a.clone()), 0),
            V2LaneIngressOutcome::Inserted
        );
        assert_eq!(
            adapter.accept_lane_message_with_ingress_ownership(admitted(hub_b, route_b.clone()), 0),
            V2LaneIngressOutcome::Inserted
        );
        let effect = adapter
            .drain_effects(1)
            .pop()
            .expect("one coalesced durable response");
        let V2LaneWorkEffect::PostDurableLaneCertificate {
            reply_routes: Some(reply_routes),
            ingress_ownership: Some(ownership),
            certificate,
            ..
        } = effect
        else {
            panic!("durable response retains routes and fair ownership")
        };
        assert_eq!(
            certificate,
            LaneBlockCertificateV1 {
                proposal: session.proposal.clone(),
                prepare_qc: session.prepare_qc.clone(),
                commit_qc: session.commit_qc.clone(),
            }
        );
        assert_eq!(reply_routes.len(), 2);
        assert!(
            reply_routes
                .iter()
                .any(|route| route.same_delivery(&route_a))
        );
        assert!(
            reply_routes
                .iter()
                .any(|route| route.same_delivery(&route_b))
        );
        assert!(ownership.validate_exact());
        assert_eq!(ownership.admission_count, 2);
        assert!(ownership.matches_reply_routes(Some(&reply_routes)));
        let hub_c = PeerId::new(KeyPair::random().public_key().clone());
        let hub_d = PeerId::new(KeyPair::random().public_key().clone());
        let route_c = route_fixture.mint_via(requester.clone(), hub_c.clone());
        let route_d = route_fixture.mint_via(requester.clone(), hub_d.clone());
        let race_effect = |via: PeerId, route: NetworkReplyRoute| {
            let mut inbound = admitted(via, route);
            let ingress_ownership = inbound
                .take_ingress_ownership()
                .expect("fair admission attaches exact ownership");
            let (_, peer, reply_routes) = inbound.into_message_sender_and_reply_routes();
            V2LaneWorkEffect::PostDurableLaneCertificate {
                peer,
                reply_routes,
                ingress_ownership: Some(ingress_ownership),
                certificate: certificate.clone(),
            }
        };
        let mut queued = race_effect(hub_c, route_c.clone());
        let candidate = race_effect(hub_d, route_d.clone());
        assert!(merge_lane_work_effect_reply_routes_after_route_merge(
            &mut queued,
            &candidate,
            || assert!(route_fixture.retire(&route_c))
        ));
        let V2LaneWorkEffect::PostDurableLaneCertificate {
            reply_routes: Some(mut race_routes),
            ingress_ownership: Some(mut race_ownership),
            ..
        } = queued
        else {
            panic!("coalesced race result retains route and ownership carriers")
        };
        assert_eq!(
            race_routes.len(),
            2,
            "source C retired after the authoritative merge snapshot"
        );
        assert!(
            race_routes
                .iter()
                .any(|route| route.same_delivery(&route_c))
        );
        assert!(
            race_routes
                .iter()
                .any(|route| route.same_delivery(&route_d)),
            "source C retirement cannot consume independent source D"
        );
        assert!(race_ownership.validate_exact());
        assert!(race_ownership.matches_reply_routes(Some(&race_routes)));
        let (retained, prune_receipt) = race_routes.retain_active_with_receipt();
        assert_eq!(
            retained, 1,
            "the next bounded snapshot observes only source C's retirement"
        );
        race_routes = race_ownership
            .project_retained_reply_routes(prune_receipt)
            .expect("the prune receipt owns the exact source-D output");
        assert!(race_ownership.validate_exact());
        assert!(race_ownership.matches_reply_routes(Some(&race_routes)));
        assert!(
            race_ownership
                .current_reply_routes()
                .is_some_and(|routes| routes.len() == 1
                    && routes.iter().any(|route| route.same_delivery(&route_d)))
        );
    }
    #[test]
    fn durable_lane_certificate_serves_rotated_validator_after_pressure() {
        let (mut adapter, keys) = fixture_at_height(wire::ConsensusMode::Permissioned, 1);
        let requester = adapter
            .context
            .roster
            .iter()
            .map(|entry| entry.validator.clone())
            .find(|peer| peer != &adapter.local_peer)
            .expect("fixture has a remote current validator");
        let historical_keys = keys
            .iter()
            .filter(|key| key.public_key() != requester.public_key())
            .cloned()
            .collect::<Vec<_>>();
        let lane_incarnation = adapter
            .state
            .lane_incarnation_at_height(LaneId::SINGLE, adapter.context.height)
            .expect("default lane incarnation");
        let proposal = proposal_for_route(
            &adapter,
            &historical_keys,
            LaneId::SINGLE,
            DataSpaceId::UNIVERSAL,
            lane_incarnation,
            adapter.context.height,
            1,
        );
        let proposal = store_canonical_anchor(&adapter, &proposal, &historical_keys[0]);
        let session = committed_lane_session(&proposal, &historical_keys);
        assert!(!session.commit_qc.validator_set.contains(&requester));
        let pops = adapter.pops_for_lane_session(&session);
        adapter
            .kura
            .persist_committed_lane_block_session(&session, &pops)
            .expect("persist historical-committee certificate");
        adapter.effects.clear();
        adapter.effect_keys.clear();
        adapter.limits.effect_capacity = NonZeroUsize::new(1).expect("non-zero capacity");
        assert!(adapter.push_effect(V2LaneWorkEffect::PostLaneBlock {
            peer: requester.clone(),
            message: BlockMessage::LaneBlockProposal(proposal.clone()),
        }));
        let mut routes = NetworkReplyRouteTestFixture::new(requester.clone());
        let requester_route = routes.mint(requester.clone());
        assert_eq!(
            adapter.accept_lane_message(
                InboundBlockMessage::try_from_transport_with_reply_route(
                    BlockMessage::LaneBlockProposal(proposal.clone()),
                    requester.clone(),
                    requester.clone(),
                    requester_route.clone(),
                )
                .expect("active historical request route"),
                0,
            ),
            V2LaneIngressOutcome::Duplicate,
            "a full response slot must leave reconstruction at the requester's exact proposal"
        );
        let _ = adapter.drain_effects(1);
        let unauthorized = PeerId::new(
            KeyPair::try_from_seed(vec![0xE7; 32], Algorithm::BlsNormal)
                .expect("outsider key")
                .public_key()
                .clone(),
        );
        let mut unauthorized_routes = NetworkReplyRouteTestFixture::new(unauthorized.clone());
        let unauthorized_route = unauthorized_routes.mint(unauthorized.clone());
        assert_eq!(
            adapter.accept_lane_message(
                InboundBlockMessage::try_from_transport_with_reply_route(
                    BlockMessage::LaneBlockProposal(proposal.clone()),
                    unauthorized.clone(),
                    unauthorized.clone(),
                    unauthorized_route,
                )
                .expect("active unauthorized route reaches consensus validation"),
                0,
            ),
            V2LaneIngressOutcome::Rejected,
            "an authenticated transport identity outside both canonical rosters is unauthorized"
        );
        assert_eq!(
            adapter.accept_lane_message(
                InboundBlockMessage::try_from_transport_with_reply_route(
                    BlockMessage::LaneBlockProposal(proposal.clone()),
                    requester.clone(),
                    requester.clone(),
                    requester_route.clone(),
                )
                .expect("active retried request route"),
                0,
            ),
            V2LaneIngressOutcome::Inserted,
            "the durable request must reconstruct the atomic response after capacity opens"
        );
        assert!(matches!(
            adapter.drain_effects(1).as_slice(),
            [V2LaneWorkEffect::PostDurableLaneCertificate {
                peer,
                reply_routes: Some(emitted_routes),
                certificate,
                ..
            }] if peer == &requester
                && emitted_routes.len() == 1
                && emitted_routes
                    .iter()
                    .any(|emitted_route| emitted_route.same_delivery(&requester_route))
                && certificate.proposal == session.proposal
        ));
    }
    #[test]
    fn decided_lane_accepts_atomic_certificate_recovery_and_rejects_mismatch() {
        let (mut adapter, keys) = fixture(wire::ConsensusMode::Permissioned);
        let (block, proposal) = planned_lane_candidate_block_at_view(&adapter, &keys, 0);
        let (locked_round, locked_subject) =
            mark_global_body_locked_for_block(&mut adapter, &block);
        assert_ne!(
            adapter.bind_locked_global_body(&block),
            V2LaneIngressOutcome::Rejected
        );
        let _ = adapter.drain_effects(usize::MAX);
        adapter
            .retain_merge_sidecars_for_global_view(
                locked_round.view,
                Some(locked_subject),
                Some(locked_subject),
            )
            .expect("install the exact decided carrier");
        let certificate = LaneBlockCertificateV1 {
            proposal: proposal.clone(),
            prepare_qc: lane_qc_for_phase(&proposal, &keys, CertPhase::Prepare),
            commit_qc: lane_qc_for_phase(&proposal, &keys, CertPhase::Commit),
        };
        let mut mismatched = certificate.clone();
        mismatched.prepare_qc.body.phase = CertPhase::Commit;
        let before = adapter.lane_sessions.len();
        assert_eq!(
            accept_lane_message_from(
                &mut adapter,
                BlockMessage::LaneBlockCertificate(Box::new(mismatched)),
                keys[0].public_key().clone().into(),
                locked_round.view,
            ),
            V2LaneIngressOutcome::Rejected
        );
        assert_eq!(adapter.lane_sessions.len(), before);
        assert_eq!(
            accept_lane_message_from(
                &mut adapter,
                BlockMessage::LaneBlockCertificate(Box::new(certificate)),
                keys[0].public_key().clone().into(),
                locked_round.view,
            ),
            V2LaneIngressOutcome::Inserted
        );
        assert_eq!(adapter.pending_committed_lanes.len(), 1);
        assert!(adapter.has_pending_committed_output_handoff());
    }
    #[test]
    fn historical_certificate_survives_successor_lock_decision_persistence_and_restart() {
        let (adapter, keys) = fixture_at_height(wire::ConsensusMode::Permissioned, 1);
        let (parent_block, proposal) = globally_anchored_lane_block_fixture(&adapter, &keys);
        adapter
            .kura
            .store_block(parent_block.clone())
            .expect("persist the globally committed lane carrier");
        let committed_parent = ValidBlock::committed_from_replay_signed_block(parent_block.clone());
        commit_test_block_to_state(adapter.state.as_ref(), &committed_parent, &adapter.context);
        let certificate = LaneBlockCertificateV1 {
            proposal: proposal.clone(),
            prepare_qc: lane_qc_for_phase(&proposal, &keys, CertPhase::Prepare),
            commit_qc: lane_qc_for_phase(&proposal, &keys, CertPhase::Commit),
        };
        let successor_context = successor_context_for_parent(&adapter, &parent_block);
        let restart = LaneAdapterRestartParts::capture(&adapter);
        let state = Arc::clone(&restart.state);
        let kura = Arc::clone(&restart.kura);
        drop(adapter);
        let mut successor = restart
            .reopen(successor_context.clone(), true)
            .expect("open the true successor-height adapter");
        assert!(
            successor
                .lane_sessions
                .proposals_without_commit_qc()
                .iter()
                .any(|pending| pending == &proposal),
            "the successor must hydrate the exact older proposal as its request source"
        );
        let _ = successor.drain_effects(usize::MAX);
        assert_eq!(
            accept_lane_message_from(
                &mut successor,
                BlockMessage::LaneBlockCertificate(Box::new(certificate)),
                PeerId::new(keys[0].public_key().clone()),
                0,
            ),
            V2LaneIngressOutcome::Inserted
        );
        assert_eq!(successor.historical_recovery_sessions.len(), 1);
        assert!(
            successor.pending_committed_lanes.is_empty(),
            "historical evidence must not enter current-carrier persistence ownership"
        );
        assert!(
            successor.committed_lane_outputs.is_empty(),
            "historical recovery must not create a fresh CommitQC fanout"
        );
        let successor_block = test_block(
            successor.context.height,
            Some(parent_block.hash()),
            None,
            &keys[0],
        );
        let (locked_round, locked_subject) =
            mark_global_body_locked_for_block(&mut successor, &successor_block);
        successor
            .retain_merge_sidecars_for_global_view(
                locked_round.view,
                Some(locked_subject),
                Some(locked_subject),
            )
            .expect("install a distinct successor Decision");
        assert_eq!(
            successor.historical_recovery_sessions.len(),
            1,
            "successor lock and Decision filtering must preserve the historical owner"
        );
        let successor_finality = finality_artifact_for_block(&successor, &keys, &successor_block);
        assert!(successor.has_pending_historical_recovery());
        assert!(
            successor
                .durable_lane_rollover_authority(&successor_finality)
                .expect("inspect historical recovery rollover gate")
                .is_none(),
            "a volatile committed historical session must not cross another successor boundary"
        );
        assert!(matches!(
            successor
                .service_next_historical_recovery()
                .expect("persist historical certificate and application witness"),
            HistoricalRecoveryServiceOutcome::Complete(_)
        ));
        assert!(!successor.has_pending_historical_recovery());
        assert_eq!(
            kura.read_certified_lane_block_artifact(
                proposal.descriptor.lane_id,
                proposal.descriptor.lane_block_height,
            )
            .map(|artifact| artifact.proposal),
            Some(proposal.clone())
        );
        assert!(kura.lane_block_application_receipt_available(&proposal));
        assert!(
            state
                .unapplied_lane_block_artifact_heights_snapshot_cached()
                .is_empty(),
            "the recovered application witness must unblock the lane frontier"
        );
        let delayed_prepare_qc = lane_qc_for_phase(&proposal, &keys[..3], CertPhase::Prepare);
        let delayed_prepare_pops = successor.pops_for_lane_qc(&delayed_prepare_qc);
        assert_eq!(
            successor
                .lane_sessions
                .insert_qc_with_pops(delayed_prepare_qc, &delayed_prepare_pops),
            Ok(LaneBlockSessionInsertOutcome::Inserted),
            "model a terminal QC restored from a bounded volatile cache"
        );
        assert!(
            !successor.has_pending_historical_recovery(),
            "a terminal Kura-backed historical QC must not wedge the next rollover"
        );
        drop(successor);
        let reopened = restart
            .reopen(successor_context, true)
            .expect("restart after historical recovery remains self-sufficient");
        assert!(!reopened.has_pending_historical_recovery());
        assert!(reopened.historical_recovery_requests.is_empty());
        assert!(reopened.historical_recovery_request_owners.is_empty());
        assert!(
            state
                .unapplied_lane_block_artifact_heights_snapshot_cached()
                .is_empty()
        );
    }
    #[test]
    fn historical_losing_certificate_cannot_conflict_with_durable_canonical_slot() {
        let (adapter, keys) = fixture_at_height(wire::ConsensusMode::Permissioned, 1);
        let (parent_block, winning_proposal) =
            globally_anchored_lane_block_fixture(&adapter, &keys);
        adapter
            .kura
            .store_block(parent_block.clone())
            .expect("persist the canonical winning carrier");
        let committed_parent = ValidBlock::committed_from_replay_signed_block(parent_block.clone());
        commit_test_block_to_state(adapter.state.as_ref(), &committed_parent, &adapter.context);
        let durable_session = committed_lane_session(&winning_proposal, &keys[..3]);
        adapter
            .kura
            .persist_committed_lane_block_session(&durable_session, &lane_signer_pops(&keys[..3]))
            .expect("persist the canonical winning lane certificate");
        let mut losing_ownership = ownership_from_proposal(&winning_proposal);
        losing_ownership.accepted_transaction_hashes =
            vec![Hash::new(b"late certified losing lane proposal")];
        let losing_replay = losing_ownership
            .compute_replay_hashes()
            .expect("derive internally consistent losing ownership");
        losing_ownership.subject_hash = losing_replay.subject_hash;
        losing_ownership.payload_ownership_hash = losing_replay.payload_ownership_hash;
        losing_ownership.rbc_instance_hash = losing_replay.rbc_instance_hash;
        losing_ownership.lane_block_descriptor_hash =
            Some(losing_replay.lane_block_descriptor_hash);
        let losing_proposal = proposal_from_ownership(&losing_ownership, parent_block.hash())
            .expect("construct the losing proposal with the winning carrier hint");
        assert_ne!(losing_proposal, winning_proposal);
        assert!(
            !adapter.historical_block_anchors_proposal(&parent_block, &losing_proposal),
            "copying a canonical block hint must not make a losing proposal canonical"
        );
        let losing_certificate = LaneBlockCertificateV1 {
            proposal: losing_proposal.clone(),
            prepare_qc: lane_qc_for_phase(&losing_proposal, &keys, CertPhase::Prepare),
            commit_qc: lane_qc_for_phase(&losing_proposal, &keys, CertPhase::Commit),
        };
        let successor_context = successor_context_for_parent(&adapter, &parent_block);
        let restart = LaneAdapterRestartParts::capture(&adapter);
        drop(adapter);
        let mut successor = restart
            .reopen(successor_context, true)
            .expect("open the true successor-height adapter");
        assert_eq!(
            accept_lane_message_from(
                &mut successor,
                BlockMessage::LaneBlockCertificate(Box::new(losing_certificate.clone())),
                PeerId::new(keys[0].public_key().clone()),
                0,
            ),
            V2LaneIngressOutcome::Rejected,
            "historical ingress must require exact canonical carrier membership"
        );
        assert!(successor.historical_recovery_sessions.is_empty());
        successor
            .historical_recovery_sessions
            .push_back(committed_lane_session_from_certificate(&losing_certificate));
        assert!(matches!(
            successor
                .service_next_historical_recovery()
                .expect("the losing proof is retired without touching the durable winner"),
            HistoricalRecoveryServiceOutcome::Complete(_)
        ));
        assert!(!successor.has_pending_historical_recovery());
        assert!(!successor.output_guard.restart_required());
        let durable = successor
            .kura
            .read_certified_lane_block_artifact(
                winning_proposal.descriptor.lane_id,
                winning_proposal.descriptor.lane_block_height,
            )
            .expect("the durable winner remains authoritative");
        assert_eq!(durable.proposal, durable_session.proposal);
        assert_eq!(durable.prepare_qc, durable_session.prepare_qc);
        assert_eq!(durable.commit_qc, durable_session.commit_qc);
    }
    #[test]
    fn historical_alternative_qc_reuses_durable_proposal_identity() {
        let (mut adapter, keys) = fixture_at_height(wire::ConsensusMode::Permissioned, 1);
        let (parent_block, proposal) = globally_anchored_lane_block_fixture(&adapter, &keys);
        adapter
            .kura
            .store_block(parent_block.clone())
            .expect("persist the canonical historical carrier");
        let finality = verified_finality_artifact_for_block(&adapter, &keys, &parent_block);
        let _commit_receipt = adapter
            .kura
            .store_v2_finality_artifact(&finality)
            .expect("persist the frozen historical validator PoP authority");
        let committed_parent = ValidBlock::committed_from_replay_signed_block(parent_block.clone());
        commit_test_block_to_state(adapter.state.as_ref(), &committed_parent, &adapter.context);
        let durable_session = committed_lane_session(&proposal, &keys[..3]);
        adapter
            .kura
            .persist_committed_lane_block_session(&durable_session, &lane_signer_pops(&keys[..3]))
            .expect("persist the first valid quorum proof");
        assert!(
            !adapter
                .kura
                .lane_block_application_receipt_available(&proposal),
            "fixture must stop between certificate and receipt durability"
        );
        let replayed = LaneBlockCertificateV1 {
            proposal: proposal.clone(),
            prepare_qc: lane_qc_for_phase(&proposal, &keys[1..], CertPhase::Prepare),
            commit_qc: lane_qc_for_phase(&proposal, &keys[1..], CertPhase::Commit),
        };
        assert_ne!(
            replayed.prepare_qc.signers_bitmap, durable_session.prepare_qc.signers_bitmap,
            "fixture must use distinct valid quorum subsets"
        );
        adapter.context = successor_context_for_parent(&adapter, &parent_block);
        assert!(proposal.descriptor.proposal_height < adapter.context.height);
        {
            let mut world = adapter.state.world.block();
            for key in &keys {
                world
                    .consensus_keys_by_pk
                    .insert(key.public_key().to_string(), Vec::new());
            }
            world.commit();
        }
        assert_eq!(
            accept_lane_message_from(
                &mut adapter,
                BlockMessage::LaneBlockCertificate(Box::new(replayed)),
                PeerId::new(keys[0].public_key().clone()),
                0,
            ),
            V2LaneIngressOutcome::Inserted,
            "the alternate proof must enter the historical recovery owner"
        );
        assert!(matches!(
            adapter
                .service_next_historical_recovery()
                .expect("an alternate quorum proof for the same proposal completes recovery"),
            HistoricalRecoveryServiceOutcome::Complete(_)
        ));
        assert!(adapter.historical_recovery_sessions.is_empty());
        assert!(
            adapter
                .kura
                .lane_block_application_receipt_available(&proposal),
            "alternate proof recovery must finish the interrupted application receipt"
        );
        let durable = adapter
            .kura
            .read_certified_lane_block_artifact(
                proposal.descriptor.lane_id,
                proposal.descriptor.lane_block_height,
            )
            .expect("retain the first durable quorum proof");
        assert_eq!(durable.prepare_qc, durable_session.prepare_qc);
        assert_eq!(durable.commit_qc, durable_session.commit_qc);
        assert!(!adapter.output_guard.restart_required());
    }
    fn self_contained_historical_recovery_request_fixture() -> (
        V2LaneWorkAdapter,
        Vec<KeyPair>,
        LaneHistoricalRecoveryRequestV1,
    ) {
        self_contained_historical_recovery_request_fixture_with_kura(locked_lane_work_test_kura(
            iroha_config::parameters::defaults::kura::BLOCKS_IN_MEMORY,
        ))
    }
    fn self_contained_historical_recovery_request_fixture_with_kura(
        kura: Arc<Kura>,
    ) -> (
        V2LaneWorkAdapter,
        Vec<KeyPair>,
        LaneHistoricalRecoveryRequestV1,
    ) {
        let (adapter, keys) =
            fixture_at_height_inner_with_kura(wire::ConsensusMode::Permissioned, 1, false, kura);
        let (block, proposal) = globally_anchored_lane_block_fixture(&adapter, &keys);
        adapter
            .kura
            .store_block(block.clone())
            .expect("persist historical request carrier");
        let finality = verified_finality_artifact_for_block(&adapter, &keys, &block);
        let _finality_receipt = adapter
            .kura
            .store_v2_finality_artifact(&finality)
            .expect("persist historical request finality");
        let committed = ValidBlock::committed_from_replay_signed_block(block.clone());
        commit_test_block_to_state(adapter.state.as_ref(), &committed, &adapter.context);
        let certificate = LaneBlockCertificateV1 {
            proposal: proposal.clone(),
            prepare_qc: lane_qc_for_phase(&proposal, &keys, CertPhase::Prepare),
            commit_qc: lane_qc_for_phase(&proposal, &keys, CertPhase::Commit),
        };
        let successor_context = successor_context_for_parent(&adapter, &block);
        let restart = LaneAdapterRestartParts::capture(&adapter);
        drop(adapter);
        let successor = restart
            .reopen(successor_context, true)
            .expect("open historical request source at successor height");
        let request = LaneHistoricalRecoveryRequestV1 {
            version: LANE_HISTORICAL_RECOVERY_VERSION_V1,
            requester: restart.local_peer,
            certificate: Some(certificate),
            signer_pops: lane_signer_pops(&keys),
            kind: LaneHistoricalRecoveryKindV1::CanonicalBlock {
                finality_artifact_hash: HashOf::new(&finality),
            },
        };
        (successor, keys, request)
    }
    fn canonical_executed_block_recovery_fixture() -> (
        V2LaneWorkAdapter,
        Vec<KeyPair>,
        SignedBlock,
        wire::finality::V2FinalityArtifact,
    ) {
        let (adapter, keys) = fixture_at_height_inner_with_kura(
            wire::ConsensusMode::Permissioned,
            2,
            true,
            locked_lane_work_test_kura(
                NonZeroUsize::new(1).expect("retain one canonical recovery body"),
            ),
        );
        let (block, _) = globally_anchored_lane_block_fixture(&adapter, &keys);
        adapter
            .kura
            .store_block(block.clone())
            .expect("persist canonical executed-block recovery fixture");
        let mut finality = verified_finality_artifact_for_block(&adapter, &keys, &block);
        retain_exact_remote_finality_quorum(&adapter, &keys, &mut finality);
        let finality_receipt = adapter
            .kura
            .store_v2_finality_artifact(&finality)
            .expect("persist canonical executed-block recovery finality");
        assert_eq!(finality_receipt.height(), block.header().height().get());
        assert_eq!(finality_receipt.block_hash(), block.hash());
        commit_test_block_to_state(
            adapter.state.as_ref(),
            &ValidBlock::committed_from_replay_signed_block(block.clone()),
            &adapter.context,
        );
        (adapter, keys, block, finality)
    }
    fn canonical_executed_block_need(
        block: &SignedBlock,
        finality: &wire::finality::V2FinalityArtifact,
    ) -> CanonicalExecutedBlockNeedV1 {
        CanonicalExecutedBlockNeedV1 {
            height: finality.height,
            block_hash: block.hash(),
            finality_artifact_hash: HashOf::new(finality),
            execution_commitment: finality.commit_qc.execution_commitment,
            executed_block_wire_len: finality
                .commit_qc
                .execution_commitment
                .executed_block_wire_len,
            executed_block_wire_hash: block
                .executed_block_wire_hash()
                .expect("hash canonical executed-block fixture wire"),
        }
    }
    fn evict_canonical_executed_block_fixture(
        adapter: &V2LaneWorkAdapter,
        keys: &[KeyPair],
        block: &SignedBlock,
    ) {
        let block_height = block.header().height().get();
        let height = NonZeroUsize::new(
            usize::try_from(block_height).expect("canonical fixture height fits usize"),
        )
        .expect("canonical fixture height is non-zero");
        let leader_index =
            usize::try_from(adapter.context.leader(0)).expect("fixture leader index fits usize");
        let tail = test_block(
            block_height.saturating_add(1),
            Some(block.hash()),
            None,
            &keys[leader_index],
        );
        adapter
            .kura
            .store_block(tail.clone())
            .expect("persist canonical recovery eviction tail");
        commit_test_block_to_state(
            adapter.state.as_ref(),
            &ValidBlock::committed_from_replay_signed_block(tail),
            &adapter.context,
        );
        let (durable_height, payload_len) = adapter
            .kura
            .durable_block_payload_len_by_hash(block.hash())
            .expect("read canonical recovery durable length authority");
        assert_eq!(durable_height, block_height);
        assert_eq!(
            adapter.kura.advertise_required_replicas_for_bench(height),
            Some(payload_len),
            "fixture must authenticate every selected remote keeper"
        );
        let freed = adapter
            .kura
            .evict_block_bodies(payload_len)
            .expect("evict canonical recovery fixture body");
        assert!(
            freed >= payload_len,
            "an evictable first owner must reclaim the complete target wire"
        );
        adapter
            .kura
            .remove_evicted_block_sidecar_for_testing(height)
            .expect("remove local canonical recovery sidecar");
        assert!(
            adapter
                .kura
                .get_block_without_merge_sidecar(height)
                .is_none()
        );
        assert_eq!(
            adapter.kura.durable_block_payload_len_by_hash(block.hash()),
            Some((block_height, payload_len)),
            "eviction must retain the exact finality-bound wire length authority"
        );
    }
    fn canonical_executed_block_request(
        requester: PeerId,
        need: CanonicalExecutedBlockNeedV1,
        chunk_index: u32,
    ) -> LaneHistoricalRecoveryRequestV1 {
        LaneHistoricalRecoveryRequestV1 {
            version: LANE_HISTORICAL_RECOVERY_VERSION_V1,
            requester,
            certificate: None,
            signer_pops: BTreeMap::new(),
            kind: LaneHistoricalRecoveryKindV1::CanonicalExecutedBlock {
                need: Box::new(need),
                chunk_index,
            },
        }
    }
    fn drain_canonical_executed_block_request(
        recovery: &mut CanonicalExecutedBlockRecovery,
    ) -> (PeerId, LaneHistoricalRecoveryRequestV1) {
        let effect = recovery
            .drain_effects(1)
            .pop()
            .expect("canonical recovery emits one request");
        let V2LaneWorkEffect::PostLaneBlock { peer, message } = effect else {
            panic!("canonical recovery request must use lane transport");
        };
        let BlockMessage::LaneHistoricalRecoveryRequest(request) = message else {
            panic!("canonical recovery effect must carry a historical request");
        };
        (peer, *request)
    }
    #[test]
    fn normal_lane_adapter_serves_certificate_free_canonical_executed_block_chunks() {
        let (mut adapter, keys, _) = self_contained_historical_recovery_request_fixture();
        let height = NonZeroUsize::new(1).expect("non-zero canonical fixture height");
        let block = adapter
            .kura
            .get_block_without_merge_sidecar(height)
            .expect("read canonical executed-block fixture");
        let finality = adapter
            .kura
            .v2_finality_artifact(1)
            .expect("read canonical fixture finality")
            .expect("canonical fixture finality exists");
        let need = canonical_executed_block_need(&block, &finality);
        let requester = keys
            .iter()
            .map(|key| PeerId::new(key.public_key().clone()))
            .find(|peer| peer != &adapter.local_peer)
            .expect("fixture has a remote finality signer");
        let request = canonical_executed_block_request(requester.clone(), need, 0);
        assert_eq!(request.source_height(), 1);
        assert!(request.certificate.is_none());
        assert!(request.signer_pops.is_empty());
        let outsider = PeerId::new(
            KeyPair::try_from_seed(vec![0xE1; 32], Algorithm::BlsNormal)
                .expect("derive outsider")
                .public_key()
                .clone(),
        );
        assert!(
            build_canonical_executed_block_response(
                &adapter.context,
                adapter.state.as_ref(),
                adapter.kura.as_ref(),
                adapter.limits,
                &adapter.local_peer,
                &request,
                &outsider,
            )
            .is_err(),
            "transport sender must be the exact authenticated requester"
        );
        assert!(
            build_canonical_executed_block_response(
                &adapter.context,
                adapter.state.as_ref(),
                adapter.kura.as_ref(),
                adapter.limits,
                &outsider,
                &request,
                &requester,
            )
            .is_err(),
            "a non-CommitQC responder cannot serve the canonical wire"
        );
        let mut wrong_need = request.clone();
        let LaneHistoricalRecoveryKindV1::CanonicalExecutedBlock { need, .. } =
            &mut wrong_need.kind
        else {
            panic!("fixture request is canonical executed-block recovery");
        };
        need.finality_artifact_hash =
            HashOf::from_untyped_unchecked(Hash::new(b"wrong canonical executed-block finality"));
        assert!(
            build_canonical_executed_block_response(
                &adapter.context,
                adapter.state.as_ref(),
                adapter.kura.as_ref(),
                adapter.limits,
                &adapter.local_peer,
                &wrong_need,
                &requester,
            )
            .is_err(),
            "the source requires the requester's exact local finality identity"
        );
        adapter.effects.clear();
        assert_eq!(
            adapter.serve_historical_recovery_request(request.clone(), Some(&requester)),
            V2LaneIngressOutcome::Inserted
        );
        let effect = adapter
            .drain_effects(1)
            .pop()
            .expect("normal adapter emits one canonical recovery response");
        let V2LaneWorkEffect::PostLaneBlock { peer, message } = effect else {
            panic!("canonical recovery response must use lane transport");
        };
        assert_eq!(peer, requester);
        let BlockMessage::LaneHistoricalRecoveryResponse(response) = message else {
            panic!("normal adapter must emit a historical recovery response");
        };
        assert_eq!(response.request_hash, HashOf::new(&request));
        let LaneHistoricalRecoveryPayloadV1::CanonicalExecutedBlockChunk {
            finality_artifact,
            wire_len,
            chunk_index,
            chunk_count,
            bytes,
        } = response.payload
        else {
            panic!("normal adapter must emit a canonical executed-block chunk");
        };
        let canonical_wire = block.encode_wire().expect("encode canonical fixture wire");
        assert_eq!(finality_artifact, finality);
        assert_eq!(
            wire_len,
            u64::try_from(canonical_wire.len()).expect("wire length fits u64")
        );
        assert_eq!(chunk_index, 0);
        assert_eq!(
            usize::try_from(chunk_count).expect("chunk count fits usize"),
            canonical_wire
                .len()
                .div_ceil(CANONICAL_EXECUTED_BLOCK_CHUNK_BYTES)
        );
        assert_eq!(bytes, canonical_wire[..bytes.len()]);
    }
    include!("v2_lane_work/canonical_executed_block_recovery_drift_test.rs");
    #[test]
    #[allow(clippy::too_many_lines)]
    fn canonical_executed_block_multichunk_restarts_whole_wire_after_byzantine_signer() {
        let (adapter, keys) = fixture_at_height_inner_with_kura(
            wire::ConsensusMode::Permissioned,
            2,
            true,
            locked_lane_work_test_kura(
                NonZeroUsize::new(1).expect("retain one multi-chunk recovery body"),
            ),
        );
        let transaction_key =
            KeyPair::try_from_seed(vec![0xE3; 32], Algorithm::Ed25519).expect("transaction key");
        let transaction = TransactionBuilder::new(
            adapter.context.network_id,
            AccountId::new(transaction_key.public_key().clone()),
            iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
        )
        .with_instructions([Log::new(
            Level::INFO,
            "m".repeat(CANONICAL_EXECUTED_BLOCK_CHUNK_BYTES + 4 * 1024),
        )])
        .sign(transaction_key.private_key());
        let entrypoint_hash = transaction.hash_as_entrypoint();
        let header = BlockHeader::new(
            NonZeroU64::new(adapter.context.height).expect("non-zero canonical height"),
            adapter
                .context
                .parent_commit_qc
                .as_ref()
                .map(|qc| qc.subject.block_hash),
            None,
            None,
            adapter.context.height,
            0,
        );
        let leader_index =
            usize::try_from(adapter.context.leader(0)).expect("fixture leader index fits usize");
        let mut builder = BlockBuilder::new(header);
        builder.push_transaction(transaction);
        let mut canonical_block = builder.build_with_signature(
            u64::try_from(leader_index).expect("leader index fits u64"),
            keys[leader_index].private_key(),
        );
        canonical_block
            .set_transaction_results(
                Vec::new(),
                &[entrypoint_hash],
                vec![TransactionResultInner::Ok(DataTriggerSequence::default())],
            )
            .expect("attach large canonical result");
        let signature = SignatureOf::try_from_hash(
            keys[leader_index].private_key(),
            canonical_block.header().hash(),
        )
        .expect("sign large result-bearing canonical block");
        canonical_block
            .replace_signatures(
                [BlockSignature::new(
                    u64::try_from(leader_index).expect("leader index fits u64"),
                    signature,
                )]
                .into_iter()
                .collect(),
            )
            .expect("replace large canonical signature");
        let canonical_wire = canonical_block
            .encode_wire()
            .expect("encode large canonical wire");
        assert_eq!(
            canonical_wire
                .len()
                .div_ceil(CANONICAL_EXECUTED_BLOCK_CHUNK_BYTES),
            2,
            "the fixture must exercise a real two-chunk canonical wire"
        );
        adapter
            .kura
            .store_block(canonical_block.clone())
            .expect("persist large canonical body");
        let mut finality = verified_finality_artifact_for_block(&adapter, &keys, &canonical_block);
        retain_exact_remote_finality_quorum(&adapter, &keys, &mut finality);
        let _finality_receipt = adapter
            .kura
            .store_v2_finality_artifact(&finality)
            .expect("persist large canonical finality");
        let committed = ValidBlock::committed_from_replay_signed_block(canonical_block.clone());
        commit_test_block_to_state(adapter.state.as_ref(), &committed, &adapter.context);
        let need = canonical_executed_block_need(&canonical_block, &finality);
        let requester = PeerId::new(
            keys.last()
                .expect("fixture validator roster is non-empty")
                .public_key()
                .clone(),
        );
        let responders = finality
            .commit_qc
            .signers
            .iter()
            .filter_map(|index| {
                usize::try_from(*index)
                    .ok()
                    .and_then(|index| finality.height_context.roster.get(index))
                    .map(|entry| entry.validator.clone())
            })
            .filter(|peer| peer != &requester)
            .collect::<Vec<_>>();
        assert!(
            responders.len() >= 2,
            "the fixture requires two remote CommitQC signers"
        );
        let byzantine = responders[0].clone();
        let honest = responders[1].clone();
        let chunk_zero_request = canonical_executed_block_request(requester.clone(), need, 0);
        let chunk_one_request = canonical_executed_block_request(requester.clone(), need, 1);
        let byzantine_chunk_zero = build_canonical_executed_block_response(
            &adapter.context,
            adapter.state.as_ref(),
            adapter.kura.as_ref(),
            adapter.limits,
            &byzantine,
            &chunk_zero_request,
            &requester,
        )
        .expect("first signer serves chunk zero before poisoning the suffix");
        let mut byzantine_chunk_one = build_canonical_executed_block_response(
            &adapter.context,
            adapter.state.as_ref(),
            adapter.kura.as_ref(),
            adapter.limits,
            &byzantine,
            &chunk_one_request,
            &requester,
        )
        .expect("first signer serves a shape-valid final chunk");
        let honest_chunk_zero = build_canonical_executed_block_response(
            &adapter.context,
            adapter.state.as_ref(),
            adapter.kura.as_ref(),
            adapter.limits,
            &honest,
            &chunk_zero_request,
            &requester,
        )
        .expect("second signer serves exact chunk zero");
        let honest_chunk_one = build_canonical_executed_block_response(
            &adapter.context,
            adapter.state.as_ref(),
            adapter.kura.as_ref(),
            adapter.limits,
            &honest,
            &chunk_one_request,
            &requester,
        )
        .expect("second signer serves exact chunk one");
        let LaneHistoricalRecoveryPayloadV1::CanonicalExecutedBlockChunk { bytes, .. } =
            &mut byzantine_chunk_one.payload
        else {
            panic!("fixture response must carry a canonical chunk");
        };
        bytes[0] ^= 1;
        evict_canonical_executed_block_fixture(&adapter, &keys, &canonical_block);
        let context = adapter.context.clone();
        let state = Arc::clone(&adapter.state);
        let kura = Arc::clone(&adapter.kura);
        let limits = adapter.limits;
        drop(adapter);
        let height = NonZeroUsize::new(
            usize::try_from(canonical_block.header().height().get())
                .expect("canonical height fits usize"),
        )
        .expect("non-zero canonical height");
        let output_guard = ConsensusOutputGuard::isolated();
        let mut recovery = CanonicalExecutedBlockRecovery::new(
            context,
            requester,
            Arc::clone(&state),
            Arc::clone(&kura),
            Arc::clone(&output_guard),
            limits,
            vec![need],
        )
        .expect("install multi-chunk canonical recovery");
        let recovery_limit = limits
            .historical_recovery_stuck_attempts
            .get()
            .saturating_mul(limits.historical_recovery_max_retry_tier.get());
        let admit = |response: LaneHistoricalRecoveryResponseV1, sender: PeerId| {
            fair_v2_ingress_admit_for_test(InboundBlockMessage::from_authenticated_peer(
                BlockMessage::LaneHistoricalRecoveryResponse(Box::new(response)),
                sender,
            ))
        };
        recovery.service_next().expect("request first chunk");
        let (first_peer, first_request) = drain_canonical_executed_block_request(&mut recovery);
        assert_eq!(first_peer, byzantine);
        assert_eq!(first_request, chunk_zero_request);
        let first_request_hash = HashOf::new(&first_request);
        assert_eq!(recovery.front_attempts, 1);
        assert_eq!(recovery.whole_wire_restarts, 0);
        assert!(recovery.effect_count() <= limits.effect_capacity.get());
        recovery
            .service_next()
            .expect("retry first chunk with the pinned signer");
        assert!(
            recovery.is_current_request_effect(
                recovery
                    .effects
                    .front()
                    .expect("the pinned retry remains queued")
            ),
            "the exact outstanding retry owns the requester deadline"
        );
        let mut wrong_responder_retry = recovery
            .effects
            .front()
            .expect("the pinned retry remains queued")
            .clone();
        let V2LaneWorkEffect::PostLaneBlock { peer, .. } = &mut wrong_responder_retry else {
            panic!("canonical recovery retries use lane transport");
        };
        *peer = honest.clone();
        assert!(
            !recovery.is_current_request_effect(&wrong_responder_retry),
            "the request bytes alone cannot refresh a different responder's deadline"
        );
        assert_eq!(recovery.front_attempts, 2);
        recovery.front_attempts = recovery_limit;
        assert_eq!(
            recovery
                .accept_with_ingress_ownership(admit(byzantine_chunk_zero, byzantine.clone()))
                .expect("accept the first signer's exact prefix"),
            V2LaneIngressOutcome::Inserted
        );
        assert_eq!(
            recovery.drain_retired_request_hashes(),
            BTreeSet::from([first_request_hash]),
            "exact prefix progress retires the prior service-owned chunk request"
        );
        assert!(
            !recovery.is_current_request_effect(
                recovery
                    .effects
                    .front()
                    .expect("the prior-chunk retry remains queued")
            ),
            "a retry becomes stale as soon as its exact response advances the chunk"
        );
        let (retry_peer, retry_request) = drain_canonical_executed_block_request(&mut recovery);
        assert_eq!(retry_peer, byzantine);
        assert_eq!(
            retry_request.encode(),
            first_request.encode(),
            "same-signer retries preserve the exact request bytes"
        );
        assert_eq!(
            recovery.front_attempts, 0,
            "exact chunk progress resets even an exhausted consecutive wait budget"
        );
        assert_eq!(recovery.whole_wire_restarts, 0);
        assert_eq!(
            recovery.assembly.len(),
            CANONICAL_EXECUTED_BLOCK_CHUNK_BYTES
        );
        assert!(recovery.assembly.len() <= STRICT_INIT_MAX_BLOCK_BYTES as usize);
        recovery.service_next().expect("request pinned suffix");
        let (suffix_peer, suffix_request) = drain_canonical_executed_block_request(&mut recovery);
        assert_eq!(suffix_peer, byzantine);
        assert_eq!(suffix_request, chunk_one_request);
        assert_eq!(recovery.front_attempts, 1);
        let retained_prefix = recovery.assembly.clone();
        let retained_next_peer_index = recovery.next_peer_index;
        let retained_responder = recovery
            .assembly_responder
            .as_ref()
            .expect("the partial wire remains pinned")
            .clone();
        let retained_request_hash = recovery
            .outstanding
            .as_ref()
            .expect("the suffix request remains outstanding")
            .request_hash;
        for _ in 0..recovery_limit {
            recovery
                .record_whole_wire_restart()
                .expect("whole-wire restart remains inside its configured bound");
        }
        let exhausted = recovery
            .accept_with_ingress_ownership(admit(byzantine_chunk_one.clone(), byzantine.clone()))
            .expect_err("an exhausted restart budget rejects a poisoned suffix");
        assert!(matches!(
            exhausted,
            V2LaneWorkError::Persistence(reason)
                if reason.contains("bounded whole-wire restarts without completion")
        ));
        assert_eq!(
            recovery.assembly, retained_prefix,
            "failed abandonment rolls the speculative poisoned suffix back"
        );
        assert_eq!(recovery.next_chunk_index, 1);
        assert_eq!(recovery.next_peer_index, retained_next_peer_index);
        assert_eq!(recovery.front_attempts, 1);
        assert_eq!(recovery.whole_wire_restarts, recovery_limit);
        let responder = recovery
            .assembly_responder
            .as_ref()
            .expect("failed abandonment retains its pinned responder");
        assert_eq!(responder.peer, retained_responder.peer);
        assert_eq!(responder.index, retained_responder.index);
        assert_eq!(responder.count, retained_responder.count);
        assert_eq!(
            recovery
                .outstanding
                .as_ref()
                .expect("failed abandonment retains its exact request")
                .request_hash,
            retained_request_hash
        );
        recovery.whole_wire_restarts = 0;
        assert_eq!(
            recovery
                .accept_with_ingress_ownership(admit(byzantine_chunk_one, byzantine.clone()))
                .expect("reject the first signer's poisoned final chunk"),
            V2LaneIngressOutcome::Rejected
        );
        assert!(recovery.assembly.is_empty());
        assert_eq!(recovery.assembly.capacity(), 0);
        assert_eq!(recovery.next_chunk_index, 0);
        assert_eq!(recovery.front_attempts, 0);
        assert_eq!(recovery.whole_wire_restarts, 1);
        recovery
            .service_next()
            .expect("restart the whole wire with the next signer");
        let (restart_peer, restart_request) = drain_canonical_executed_block_request(&mut recovery);
        assert_eq!(restart_peer, honest);
        assert_eq!(recovery.front_attempts, 1);
        assert_eq!(
            restart_request, chunk_zero_request,
            "failover discards the unverified prefix and restarts at chunk zero"
        );
        assert_eq!(
            recovery
                .accept_with_ingress_ownership(admit(honest_chunk_zero, honest.clone()))
                .expect("accept honest restart prefix"),
            V2LaneIngressOutcome::Inserted
        );
        assert_eq!(recovery.front_attempts, 0);
        assert_eq!(
            recovery.whole_wire_restarts, 1,
            "a valid prefix must not forgive an abandoned whole-wire assembly"
        );
        recovery.service_next().expect("request honest suffix");
        let (honest_suffix_peer, honest_suffix_request) =
            drain_canonical_executed_block_request(&mut recovery);
        assert_eq!(honest_suffix_peer, honest);
        assert_eq!(honest_suffix_request, chunk_one_request);
        assert_eq!(recovery.front_attempts, 1);
        recovery
            .service_next()
            .expect("retry an honest suffix after exact prefix progress");
        let (honest_retry_peer, honest_retry_request) =
            drain_canonical_executed_block_request(&mut recovery);
        assert_eq!(honest_retry_peer, honest);
        assert_eq!(honest_retry_request, chunk_one_request);
        assert_eq!(recovery.front_attempts, 2);
        assert_eq!(
            recovery
                .accept_with_ingress_ownership(admit(honest_chunk_one, honest))
                .expect("cache exact canonical wire from one honest signer"),
            V2LaneIngressOutcome::Inserted
        );
        assert!(!recovery.has_pending());
        assert_eq!(recovery.effect_count(), 0);
        assert_eq!(recovery.assembly.capacity(), 0);
        assert_eq!(recovery.front_attempts, 0);
        assert_eq!(recovery.whole_wire_restarts, 0);
        assert!(!output_guard.restart_required());
        let cached = kura
            .get_block_without_merge_sidecar(height)
            .expect("exact multi-chunk canonical body is cached");
        assert_eq!(
            cached.encode_wire().expect("encode restored body"),
            canonical_wire
        );
    }
    #[test]
    fn historical_recovery_request_rejects_missing_extra_and_tampered_signer_pops() {
        let (mut adapter, _keys, request) = self_contained_historical_recovery_request_fixture();
        assert!(
            adapter
                .validate_historical_recovery_request(&request, &request.requester)
                .is_ok(),
            "exact self-contained historical request must validate"
        );
        let mut missing = request.clone();
        let missing_key = missing
            .signer_pops
            .keys()
            .next()
            .expect("fixture signer PoP")
            .clone();
        missing.signer_pops.remove(&missing_key);
        let outsider = KeyPair::try_from_seed(vec![0xEC; 32], Algorithm::BlsNormal)
            .expect("derive extra historical PoP signer");
        let mut extra = request.clone();
        extra.signer_pops.insert(
            outsider.public_key().clone(),
            iroha_crypto::bls_normal_pop_prove(outsider.private_key())
                .expect("derive extra historical signer PoP"),
        );
        let mut tampered = request.clone();
        tampered
            .signer_pops
            .get_mut(&missing_key)
            .expect("fixture signer PoP")[0] ^= 0x01;
        for (invalid, article, defect) in [
            (&missing, "a", "missing historical signer PoP"),
            (&extra, "an", "extra historical signer PoP"),
            (&tampered, "a", "tampered historical signer PoP"),
        ] {
            assert!(
                adapter
                    .validate_historical_recovery_request(invalid, &invalid.requester)
                    .is_err(),
                "{article} {defect} must fail closed"
            );
        }
        let valid_request_len =
            BlockMessage::LaneHistoricalRecoveryRequest(Box::new(request.clone()))
                .encode()
                .len();
        adapter.limits.merge_share_frame_capacity =
            NonZeroUsize::new(valid_request_len).expect("non-zero exact request frame");
        assert!(adapter.historical_recovery_request_fits_frame(&request));
        let mut oversized = request;
        oversized
            .signer_pops
            .get_mut(&missing_key)
            .expect("fixture signer PoP")
            .push(0);
        assert!(!adapter.historical_recovery_request_fits_frame(&oversized));
        assert!(
            adapter
                .validate_historical_recovery_request(&oversized, &oversized.requester)
                .is_err(),
            "an oversized historical signer-PoP map must fail before proof validation"
        );
    }
